window.HSK_TEXTS = [{"l": 1, "texts": [{"n": 1, "zh": "对话：阿玲和小雪聊阿玲的男朋友", "vi": "Hội thoại: A Linh và Tiểu Tuyết nói về bạn trai của A Linh", "en": "Dialogue: A Linh and Xiaoxue talk about A Linh's boyfriend", "kw": ["法律", "俩", "印象", "深", "熟悉", "不仅", "性格"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，听说你男朋友周南跟你一个学校，他是你同学吗？", "p": ["ā", "líng", "", "tīng", "shuō", "nǐ", "nán", "péng", "you", "zhōu", "nán", "gēn", "nǐ", "yí", "gè", "xué", "xiào", "", "tā", "shì", "nǐ", "tóng", "xué", "ma", ""], "vi": "A Linh, nghe nói bạn trai cậu là Châu Nam học cùng trường với cậu, anh ấy là bạn cùng lớp à?", "en": "A Linh, I heard your boyfriend Zhou Nan goes to the same university as you. Is he in your class?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他学的是法律，我学的是汉语。我们俩不是一个班的。", "p": ["tā", "xué", "de", "shì", "fǎ", "lǜ", "", "wǒ", "xué", "de", "shì", "hàn", "yǔ", "", "wǒ", "men", "liǎ", "bú", "shì", "yí", "gè", "bān", "de", ""], "vi": "Anh ấy học luật, mình học tiếng Trung. Hai đứa không cùng lớp.", "en": "He studies law, and I study Chinese. The two of us aren't in the same class."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们是在什么场合认识的？", "p": ["nǐ", "men", "shì", "zài", "shén", "me", "chǎng", "hé", "rèn", "shí", "de", ""], "vi": "Hai người quen nhau trong hoàn cảnh nào?", "en": "Where did you two meet?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "上个月学校去郊外拍照，我的相机突然不能用了。他帮我弄了很久，我对他印象很深。后来我们常在图书馆见面，才慢慢熟悉起来。", "p": ["shàng", "gè", "yuè", "xué", "xiào", "qù", "jiāo", "wài", "pāi", "zhào", "", "wǒ", "de", "xiàng", "jī", "tū", "rán", "bù", "néng", "yòng", "le", "", "tā", "bāng", "wǒ", "nòng", "le", "hěn", "jiǔ", "", "wǒ", "duì", "tā", "yìn", "xiàng", "hěn", "shēn", "", "hòu", "lái", "wǒ", "men", "cháng", "zài", "tú", "shū", "guǎn", "jiàn", "miàn", "", "cái", "màn", "màn", "shú", "xī", "qǐ", "lái", ""], "vi": "Tháng trước trường tổ chức đi ngoại ô chụp ảnh, máy ảnh của mình đột nhiên hỏng. Anh ấy giúp mình sửa rất lâu, mình có ấn tượng rất sâu về anh ấy. Sau đó bọn mình thường gặp nhau ở thư viện, rồi mới dần quen thuộc.", "en": "Last month the school went to the countryside to take photos, and my camera suddenly stopped working. He spent a long time helping me with it, and that left a deep impression on me. After that we often met in the library, and slowly got to know each other."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你喜欢他，是因为这件事吗？", "p": ["nǐ", "xǐ", "huān", "tā", "", "shì", "yīn", "wèi", "zhè", "jiàn", "shì", "ma", ""], "vi": "Cậu thích anh ấy là vì chuyện đó sao?", "en": "Is that why you like him?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "不只是这样。他不仅能把很难的法律讲清楚，性格也很稳，跟他在一起我很放心。", "p": ["bù", "zhǐ", "shì", "zhè", "yàng", "", "tā", "bù", "jǐn", "néng", "bǎ", "hěn", "nán", "de", "fǎ", "lǜ", "jiǎng", "qīng", "chǔ", "", "xìng", "gé", "yě", "hěn", "wěn", "", "gēn", "tā", "zài", "yì", "qǐ", "wǒ", "hěn", "fàng", "xīn", ""], "vi": "Không chỉ vậy. Anh ấy không những giảng được luật khó một cách rõ ràng, tính cách cũng rất điềm tĩnh, ở bên anh ấy mình cảm thấy yên tâm.", "en": "It's not just that. He can not only explain difficult points of law clearly, he also has a steady character, and I feel at ease with him."}]}, {"n": 2, "zh": "对话：阿玲告诉小雪她准备结婚", "vi": "Hội thoại: A Linh nói với Tiểu Tuyết là mình định kết hôn", "en": "Dialogue: A Linh tells Xiaoxue she plans to get married", "kw": ["开玩笑", "从来", "最好", "共同", "适合", "幸福"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "小雪，我想先告诉你一件事：我和周南准备今年冬天结婚。", "p": ["xiǎo", "xuě", "", "wǒ", "xiǎng", "xiān", "gào", "sù", "nǐ", "yí", "jiàn", "shì", "", "wǒ", "hé", "zhōu", "nán", "zhǔn", "bèi", "jīn", "nián", "dōng", "tiān", "jié", "hūn", ""], "vi": "Tiểu Tuyết, mình muốn nói trước với cậu một chuyện: mình và Châu Nam định kết hôn vào mùa đông năm nay.", "en": "Xiaoxue, I want to tell you something first: Zhou Nan and I are planning to get married this winter."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你别开玩笑了！才半年，就谈结婚？", "p": ["nǐ", "bié", "kāi", "wán", "xiào", "le", "", "cái", "bàn", "nián", "", "jiù", "tán", "jié", "hūn", ""], "vi": "Cậu đừng có nói đùa! Mới có nửa năm đã bàn đến chuyện kết hôn?", "en": "Don't joke around! You've only known each other half a year, and you're already talking about marriage?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我是认真的。认识的时间不长，可我从来没这么确定过。", "p": ["wǒ", "shì", "rèn", "zhēn", "de", "", "rèn", "shí", "de", "shí", "jiān", "bù", "cháng", "", "kě", "wǒ", "cóng", "lái", "méi", "zhè", "me", "què", "dìng", "guò", ""], "vi": "Mình nói nghiêm túc đó. Thời gian quen nhau chưa dài, nhưng mình chưa bao giờ chắc chắn như vậy.", "en": "I'm serious. We haven't known each other long, but I've never been this sure."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "要一起过一辈子，最好先看看有没有共同的习惯，不然以后会很累。", "p": ["yào", "yì", "qǐ", "guò", "yí", "bèi", "zi", "", "zuì", "hǎo", "xiān", "kàn", "kàn", "yǒu", "méi", "yǒu", "gòng", "tóng", "de", "xí", "guàn", "", "bù", "rán", "yǐ", "hòu", "huì", "hěn", "lèi", ""], "vi": "Muốn sống cùng nhau cả đời thì tốt nhất hãy xem đã có những thói quen chung chưa, nếu không sau này sẽ rất mệt.", "en": "If you want to spend a lifetime together, you'd better first see whether you share habits; otherwise it will be tiring later."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我们都喜欢一大早去湖边走路，也喜欢在旧书店里一站一下午。我觉得我们很适合对方。", "p": ["wǒ", "men", "dōu", "xǐ", "huān", "yí", "dà", "zǎo", "qù", "hú", "biān", "zǒu", "lù", "", "yě", "xǐ", "huān", "zài", "jiù", "shū", "diàn", "lǐ", "yí", "zhàn", "yí", "xià", "wǔ", "", "wǒ", "jué", "de", "wǒ", "men", "hěn", "shì", "hé", "duì", "fāng", ""], "vi": "Bọn mình đều thích sáng sớm ra hồ đi bộ, cũng thích đứng cả buổi chiều trong hiệu sách cũ. Mình thấy hai đứa rất hợp nhau.", "en": "We both like walking by the lake early in the morning, and we can stand in a second-hand bookshop all afternoon. I think we suit each other well."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "听你讲这些，我倒真替你高兴。希望你们一直这么幸福。", "p": ["tīng", "nǐ", "jiǎng", "zhè", "xiē", "", "wǒ", "dào", "zhēn", "tì", "nǐ", "gāo", "xìng", "", "xī", "wàng", "nǐ", "men", "yì", "zhí", "zhè", "me", "xìng", "fú", ""], "vi": "Nghe cậu kể vậy, mình đúng là mừng cho cậu. Mong hai người mãi hạnh phúc như vậy.", "en": "Hearing you say this, I'm genuinely happy for you. I hope you two stay this happy."}]}, {"n": 3, "zh": "对话：林阿姨和赵阿姨聊婚后的日子", "vi": "Hội thoại: Thím Lâm và thím Triệu nói về cuộc sống sau khi cưới", "en": "Dialogue: Aunt Lin and Aunt Zhao talk about married life", "kw": ["生活", "刚", "浪漫", "够", "缺点", "接受"], "lines": [{"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "赵阿姨，听说您结婚快十五年了？", "p": ["zhào", "ā", "yí", "", "tīng", "shuō", "nín", "jié", "hūn", "kuài", "shí", "wǔ", "nián", "le", ""], "vi": "Thím Triệu, nghe nói thím kết hôn gần mười lăm năm rồi phải không?", "en": "Aunt Zhao, I heard you've been married for almost fifteen years?"}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "到春节就满十五年了。这些年生活不算热闹，可一直很踏实。", "p": ["dào", "chūn", "jié", "jiù", "mǎn", "shí", "wǔ", "nián", "le", "", "zhè", "xiē", "nián", "shēng", "huó", "bú", "suàn", "rè", "nào", "", "kě", "yì", "zhí", "hěn", "tā", "shi", ""], "vi": "Đến Tết là tròn mười lăm năm. Mấy năm nay cuộc sống không ồn ào, nhưng luôn rất vững vàng.", "en": "By Spring Festival it will be a full fifteen years. These years our life hasn't been lively, but it has always been steady."}, {"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "我刚结婚那两年，周末总想换一条路走走，试试新的小馆。可最近工作一忙，回家只想休息，话也少了。", "p": ["wǒ", "gāng", "jié", "hūn", "nà", "liǎng", "nián", "", "zhōu", "mò", "zǒng", "xiǎng", "huàn", "yì", "tiáo", "lù", "zǒu", "zǒu", "", "shì", "shì", "xīn", "de", "xiǎo", "guǎn", "", "kě", "zuì", "jìn", "gōng", "zuò", "yì", "máng", "", "huí", "jiā", "zhǐ", "xiǎng", "xiū", "xī", "", "huà", "yě", "shǎo", "le", ""], "vi": "Hai năm mình vừa mới cưới, cuối tuần nào cũng muốn đổi đường đi dạo, thử quán nhỏ mới. Nhưng dạo này việc một bận, về nhà chỉ muốn nghỉ, nói chuyện cũng ít đi.", "en": "In the two years after I had just got married, at weekends I always wanted to try a new path for a walk, or a new little restaurant. But lately work has been busy, I only want to rest when I get home, and we talk less."}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "两个人过日子，不能只靠那一点浪漫，那是不够的。", "p": ["liǎng", "gè", "rén", "guò", "rì", "zi", "", "bù", "néng", "zhǐ", "kào", "nà", "yì", "diǎn", "làng", "màn", "", "nà", "shì", "bú", "gòu", "de", ""], "vi": "Hai người sống với nhau không thể chỉ dựa vào chút lãng mạn ấy, như thế là không đủ.", "en": "When two people share a life, you can't rely on that bit of romance alone — it isn't enough."}, {"s": "林阿姨", "sp": ["lín", "ā", "yí"], "t": "您说得对。我现在有时候会把他的缺点看得很重，然后自己也不痛快。", "p": ["nín", "shuō", "de", "duì", "", "wǒ", "xiàn", "zài", "yǒu", "shí", "hòu", "huì", "bǎ", "tā", "de", "quē", "diǎn", "kàn", "de", "hěn", "zhòng", "", "rán", "hòu", "zì", "jǐ", "yě", "bú", "tòng", "kuai", ""], "vi": "Thím nói đúng. Giờ đôi lúc mình nhìn khuyết điểm của anh ấy quá nặng, rồi bản thân cũng không vui.", "en": "You're right. Sometimes now I dwell on his shortcomings, and then I feel unhappy myself."}, {"s": "赵阿姨", "sp": ["zhào", "ā", "yí"], "t": "一起的时间长了，谁都会有让对方不舒服的地方。接受这些，把日子往平静里过，才会轻松一些。", "p": ["yì", "qǐ", "de", "shí", "jiān", "cháng", "le", "", "shéi", "dōu", "huì", "yǒu", "ràng", "duì", "fāng", "bù", "shū", "fú", "de", "dì", "fāng", "", "jiē", "shòu", "zhè", "xiē", "", "bǎ", "rì", "zi", "wǎng", "píng", "jìng", "lǐ", "guò", "", "cái", "huì", "qīng", "sōng", "yì", "xiē", ""], "vi": "Ở bên nhau lâu, ai cũng có chỗ làm đối phương không dễ chịu. Chấp nhận những điều đó, sống ngày tháng cho bình lặng, sẽ nhẹ nhàng hơn.", "en": "When you've been together a long time, everyone has something that makes the other uncomfortable. Accept that, and live the days more calmly, and it will feel easier."}]}, {"n": 4, "zh": "短文：生活里的小浪漫", "vi": "Đoạn văn: Chút lãng mạn trong đời thường", "en": "Passage: The small romances in everyday life", "kw": ["羡慕", "爱情", "星星", "即使", "加班", "亮", "感动"], "lines": [{"s": "", "sp": [], "t": "很多人羡慕电影里的爱情，总觉得那才够浪漫。可我现在慢慢发现，真正留下来的往往是很小的事。有一次停电，爸爸指着窗外的星星给弟弟讲故事；还有一天，我即使加班到很晚，回到家也还能看见桌上那碗热汤。最让我感动的，是父母晚饭后去散步，路灯已经亮了，他们还是走得很慢，像是要把一天里没说完的话，慢慢补回来。", "p": ["hěn", "duō", "rén", "xiàn", "mù", "diàn", "yǐng", "lǐ", "de", "ài", "qíng", "", "zǒng", "jué", "de", "nà", "cái", "gòu", "làng", "màn", "", "kě", "wǒ", "xiàn", "zài", "màn", "màn", "fā", "xiàn", "", "zhēn", "zhèng", "liú", "xià", "lái", "de", "wǎng", "wǎng", "shì", "hěn", "xiǎo", "de", "shì", "", "yǒu", "yí", "cì", "tíng", "diàn", "", "bà", "bà", "zhǐ", "zhe", "chuāng", "wài", "de", "xīng", "xīng", "gěi", "dì", "di", "jiǎng", "gù", "shì", "", "hái", "yǒu", "yì", "tiān", "", "wǒ", "jí", "shǐ", "jiā", "bān", "dào", "hěn", "wǎn", "", "huí", "dào", "jiā", "yě", "hái", "néng", "kàn", "jiàn", "zhuō", "shàng", "nà", "wǎn", "rè", "tāng", "", "zuì", "ràng", "wǒ", "gǎn", "dòng", "de", "", "shì", "fù", "mǔ", "wǎn", "fàn", "hòu", "qù", "sàn", "bù", "", "lù", "dēng", "yǐ", "jīng", "liàng", "le", "", "tā", "men", "hái", "shì", "zǒu", "de", "hěn", "màn", "", "xiàng", "shì", "yào", "bǎ", "yì", "tiān", "lǐ", "méi", "shuō", "wán", "de", "huà", "", "màn", "màn", "bǔ", "huí", "lái", ""], "vi": "Nhiều người ngưỡng mộ tình yêu trong phim, cứ nghĩ thế mới đủ lãng mạn. Nhưng giờ tôi dần nhận ra, những gì thật sự còn lại thường là chuyện rất nhỏ. Có lần mất điện, bố chỉ lên những ngôi sao ngoài cửa sổ kể chuyện cho em trai; còn có một ngày, dù tôi tăng ca đến rất muộn, về nhà vẫn thấy trên bàn bát canh nóng ấy. Điều khiến tôi cảm động nhất là bố mẹ đi dạo sau bữa tối, đèn đường đã sáng họ vẫn đi rất chậm, như muốn lấy lại những câu cả ngày chưa kịp nói.", "en": "Many people envy the love in films and always feel that is what counts as romance. But I have slowly come to see that what really lasts is often something very small. Once, during a power cut, Dad pointed at the stars outside the window and told my little brother a story; and one day, even though I worked late, I could still see that bowl of hot soup on the table when I got home. What moves me most is my parents' walk after dinner: the street lights are already on, yet they still walk very slowly, as if they want to slowly make up the words they had no time for during the day."}]}, {"n": 5, "zh": "短文：走进婚姻的理由", "vi": "Đoạn văn: Lý do bước vào hôn nhân", "en": "Passage: Reasons for walking into marriage", "kw": ["自然", "原因", "互相", "吸引", "幽默", "脾气"], "lines": [{"s": "", "sp": [], "t": "提起结婚，有人会想得很远，也有人觉得这件事很自然。在我看来，两个人走进婚姻，原因不只是喜欢，还要能在想法上互相吸引。我姐姐的丈夫是中学老师，上课很幽默，学生们都爱听。他脾气很软，家里意见不一样的时候，他总是先听完再慢慢说。看着他们，我才明白，这样的相处，比甜言蜜语更让人放心。", "p": ["tí", "qǐ", "jié", "hūn", "", "yǒu", "rén", "huì", "xiǎng", "de", "hěn", "yuǎn", "", "yě", "yǒu", "rén", "jué", "de", "zhè", "jiàn", "shì", "hěn", "zì", "rán", "", "zài", "wǒ", "kàn", "lái", "", "liǎng", "gè", "rén", "zǒu", "jìn", "hūn", "yīn", "", "yuán", "yīn", "bù", "zhǐ", "shì", "xǐ", "huān", "", "hái", "yào", "néng", "zài", "xiǎng", "fǎ", "shàng", "hù", "xiāng", "xī", "yǐn", "", "wǒ", "jiě", "jiě", "de", "zhàng", "fū", "shì", "zhōng", "xué", "lǎo", "shī", "", "shàng", "kè", "hěn", "yōu", "mò", "", "xué", "shēng", "men", "dōu", "ài", "tīng", "", "tā", "pí", "qì", "hěn", "ruǎn", "", "jiā", "lǐ", "yì", "jiàn", "bù", "yí", "yàng", "de", "shí", "hòu", "", "tā", "zǒng", "shì", "xiān", "tīng", "wán", "zài", "màn", "màn", "shuō", "", "kàn", "zhe", "tā", "men", "", "wǒ", "cái", "míng", "bái", "", "zhè", "yàng", "de", "xiāng", "chǔ", "", "bǐ", "tián", "yán", "mì", "yǔ", "gèng", "ràng", "rén", "fàng", "xīn", ""], "vi": "Nhắc đến kết hôn, có người nghĩ rất xa, cũng có người thấy việc ấy rất tự nhiên. Với tôi, hai người bước vào hôn nhân, lý do không chỉ là thích nhau, mà còn phải thu hút lẫn nhau về mặt suy nghĩ. Chồng chị gái tôi là giáo viên trung học, dạy học rất hài hước, học sinh nào cũng thích nghe. Tính khí anh ấy rất dịu, khi ở nhà có ý kiến khác nhau, anh ấy luôn nghe hết rồi mới nói chậm rãi. Nhìn họ, tôi mới hiểu, cách sống bên nhau như vậy khiến người ta yên tâm hơn những lời đường mật.", "en": "When people mention marriage, some think far ahead, while others feel it is a very natural step. To me, when two people enter marriage, the reason is not only that they like each other — they also need to attract each other in the way they think. My elder sister's husband is a secondary-school teacher. He is very humorous in class, and the students love listening to him. He has a gentle temper: when they disagree at home, he always listens to the end before speaking slowly. Watching them, I finally understand that this way of being together is more reassuring than sweet words."}]}]}, {"l": 2, "texts": [{"n": 1, "zh": "对话：阿玲和阮明聊刚到中国的日子", "vi": "Hội thoại: A Linh và Nguyễn Minh nói về những ngày mới đến Trung Quốc", "en": "Dialogue: A Linh and Nguyen Minh talk about his first days in China", "kw": ["适应", "逛", "交", "平时", "短信", "正好"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，新来的同学阮明还习惯这儿吗？", "p": ["ā", "líng", "", "xīn", "lái", "de", "tóng", "xué", "ruǎn", "míng", "hái", "xí", "guàn", "zhè", "r", "ma", ""], "vi": "A Linh, bạn mới Nguyễn Minh đã quen ở đây chưa?", "en": "A Linh, has the new classmate Nguyen Minh got used to it here yet?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "他刚来的那两周，吃饭、坐车都不太适应。后来我带他去交了几个朋友，情况才好起来。", "p": ["tā", "gāng", "lái", "de", "nà", "liǎng", "zhōu", "", "chī", "fàn", "", "zuò", "chē", "dōu", "bú", "tài", "shì", "yìng", "", "hòu", "lái", "wǒ", "dài", "tā", "qù", "jiāo", "le", "jǐ", "gè", "péng", "you", "", "qíng", "kuàng", "cái", "hǎo", "qǐ", "lái", ""], "vi": "Hai tuần đầu anh ấy mới đến, ăn uống và đi xe đều không được thích nghi lắm. Sau đó mình đưa anh ấy đi kết thêm vài người bạn, mọi thứ mới khá hơn.", "en": "In the first two weeks after he arrived, meals and buses were hard to adapt to. Then I took him out to make a few friends, and things got better."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你们平时都做些什么？", "p": ["nǐ", "men", "píng", "shí", "dōu", "zuò", "xiē", "shén", "me", ""], "vi": "Bình thường các bạn làm gì?", "en": "What do you usually do?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "周末我们喜欢去逛附近的小市场，看看水果，听听大家说话。他有问题，也会给我发短信。", "p": ["zhōu", "mò", "wǒ", "men", "xǐ", "huān", "qù", "guàng", "fù", "jìn", "de", "xiǎo", "shì", "chǎng", "", "kàn", "kàn", "shuǐ", "guǒ", "", "tīng", "tīng", "dà", "jiā", "shuō", "huà", "", "tā", "yǒu", "wèn", "tí", "", "yě", "huì", "gěi", "wǒ", "fā", "duǎn", "xìn", ""], "vi": "Cuối tuần bọn mình thích đi dạo chợ nhỏ gần đó, xem trái cây, nghe mọi người nói chuyện. Có việc gì anh ấy cũng nhắn tin cho mình.", "en": "At weekends we like to stroll around the little market nearby, look at the fruit and listen to people talking. If he has a question, he also texts me."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "这个周六正好有个校园音乐会，要不要叫上他？", "p": ["zhè", "ge", "zhōu", "liù", "zhèng", "hǎo", "yǒu", "gè", "xiào", "yuán", "yīn", "yuè", "huì", "", "yào", "bú", "yào", "jiào", "shàng", "tā", ""], "vi": "Thứ bảy này đúng lúc có hòa nhạc trong trường, có gọi anh ấy không?", "en": "There's a campus concert this Saturday, as it happens — shall we ask him along?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好啊。他正想多认识点儿人，去了一定高兴。", "p": ["hǎo", "a", "", "tā", "zhèng", "xiǎng", "duō", "rèn", "shí", "diǎn", "r", "rén", "", "qù", "le", "yí", "dìng", "gāo", "xìng", ""], "vi": "Được chứ. Anh ấy đang muốn quen thêm người, đi thì chắc vui.", "en": "Yes. He wants to meet more people, so he'll be glad to come."}]}, {"n": 2, "zh": "对话：小雪为同学聚会发愁", "vi": "Hội thoại: Tiểu Tuyết lo chuyện họp lớp", "en": "Dialogue: Xiaoxue worries about a class reunion", "kw": ["聚会", "毕业", "差不多", "联系", "专门", "麻烦"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，下个月班里要办一场同学聚会，我有点儿发愁。", "p": ["ā", "líng", "", "xià", "gè", "yuè", "bān", "lǐ", "yào", "bàn", "yì", "cháng", "tóng", "xué", "jù", "huì", "", "wǒ", "yǒu", "diǎn", "r", "fā", "chóu", ""], "vi": "A Linh, tháng sau lớp mình tổ chức họp lớp, mình hơi lo.", "en": "A Linh, the class is holding a reunion next month, and I'm a bit worried."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "发愁什么？大家毕业才差不多一年，应该都还记得路吧？", "p": ["fā", "chóu", "shén", "me", "", "dà", "jiā", "bì", "yè", "cái", "chà", "bu", "duō", "yì", "nián", "", "yīng", "gāi", "dōu", "hái", "jì", "de", "lù", "ba", ""], "vi": "Lo gì? Mọi người tốt nghiệp mới được khoảng một năm, chắc vẫn nhớ đường chứ?", "en": "Why? It's only been about a year since everyone graduated — they should still remember the way, shouldn't they?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "问题是有几个人不太好联系。有的换了号码，我专门问了老师，还是没问到。", "p": ["wèn", "tí", "shì", "yǒu", "jǐ", "gè", "rén", "bú", "tài", "hǎo", "lián", "xì", "", "yǒu", "de", "huàn", "le", "hào", "mǎ", "", "wǒ", "zhuān", "mén", "wèn", "le", "lǎo", "shī", "", "hái", "shì", "méi", "wèn", "dào", ""], "vi": "Vấn đề là có vài người khá khó liên lạc. Có người đổi số, mình còn hỏi riêng giáo viên, vẫn chưa ra.", "en": "The problem is that a few people are hard to contact. Some have changed numbers. I even went out of my way to ask the teacher, and I still didn't get them."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那就先请到的人来。你已经尽力了，别把这件事变成麻烦。", "p": ["nà", "jiù", "xiān", "qǐng", "dào", "de", "rén", "lái", "", "nǐ", "yǐ", "jīng", "jìn", "lì", "le", "", "bié", "bǎ", "zhè", "jiàn", "shì", "biàn", "chéng", "má", "fán", ""], "vi": "Vậy thì mời trước những người liên lạc được. Cậu đã cố rồi, đừng biến việc này thành chuyện phiền phức.", "en": "Then just invite the people you can reach first. You've already tried your best — don't turn it into a hassle."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "说得对。我今晚先把通知发给大家，地点还是那家常去的小馆。", "p": ["shuō", "de", "duì", "", "wǒ", "jīn", "wǎn", "xiān", "bǎ", "tōng", "zhī", "fā", "gěi", "dà", "jiā", "", "dì", "diǎn", "hái", "shì", "nà", "jiā", "cháng", "qù", "de", "xiǎo", "guǎn", ""], "vi": "Đúng đó. Tối nay mình gửi thông báo trước, địa điểm vẫn là quán nhỏ mọi người hay đến.", "en": "That's right. I'll send the notice out tonight. The place can still be that little restaurant we often go to."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "需要我帮忙联系谁，你就说一声。", "p": ["xū", "yào", "wǒ", "bāng", "máng", "lián", "xì", "shuí", "", "nǐ", "jiù", "shuō", "yì", "shēng", ""], "vi": "Cần mình giúp liên lạc ai thì cậu nói một tiếng.", "en": "If you need me to help contact anyone, just say."}]}, {"n": 3, "zh": "对话：阿玲和小雪翻看夏令营的照片", "vi": "Hội thoại: A Linh và Tiểu Tuyết xem ảnh trại hè", "en": "Dialogue: A Linh and Xiaoxue look through summer-camp photos", "kw": ["好像", "重新", "尽管", "真正", "友谊", "当"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你看这张，当我们在山里教孩子们写汉字的时候，你的帽子都歪了。", "p": ["nǐ", "kàn", "zhè", "zhāng", "", "dāng", "wǒ", "men", "zài", "shān", "lǐ", "jiào", "hái", "zi", "men", "xiě", "hàn", "zì", "de", "shí", "hòu", "", "nǐ", "de", "mào", "zi", "dōu", "wāi", "le", ""], "vi": "Cậu nhìn tấm này, khi chúng mình đang dạy bọn trẻ viết chữ Hán trên núi, mũ cậu còn lệch nữa.", "en": "Look at this one — when we were teaching the children to write characters in the mountains, your hat was even crooked."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "真的好像是昨天的事。我倒想重新再去一次，再听他们喊我们“老师”。", "p": ["zhēn", "de", "hǎo", "xiàng", "shì", "zuó", "tiān", "de", "shì", "", "wǒ", "dào", "xiǎng", "chóng", "xīn", "zài", "qù", "yí", "cì", "", "zài", "tīng", "tā", "men", "hǎn", "wǒ", "men", "", "lǎo", "shī", "", ""], "vi": "Thật giống như chuyện hôm qua. Mình lại muốn đi lại một lần nữa, nghe các em gọi mình bằng «cô giáo».", "en": "It really seems like yesterday. I'd love to go again, and hear them call us \"teacher\" once more."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "尽管现在各忙各的，我还是会想起那时大家一起做饭、一起笑的晚上。", "p": ["jǐn", "guǎn", "xiàn", "zài", "gè", "máng", "gè", "de", "", "wǒ", "hái", "shì", "huì", "xiǎng", "qǐ", "nà", "shí", "dà", "jiā", "yì", "qǐ", "zuò", "fàn", "", "yì", "qǐ", "xiào", "de", "wǎn", "shàng", ""], "vi": "Dù giờ ai cũng bận việc của mình, mình vẫn nhớ những tối cả nhóm cùng nấu ăn, cùng cười.", "en": "Even though we're each busy with our own things now, I still think of those evenings when we cooked and laughed together."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "所以我说，真正让人记得住的，不是风景，是那段友谊。", "p": ["suǒ", "yǐ", "wǒ", "shuō", "", "zhēn", "zhèng", "ràng", "rén", "jì", "de", "zhù", "de", "", "bú", "shì", "fēng", "jǐng", "", "shì", "nà", "duàn", "yǒu", "yì", ""], "vi": "Nên mình mới nói, điều thật sự khiến người ta nhớ không phải phong cảnh, mà là tình bạn ấy.", "en": "That's why I say what you really remember isn't the scenery, it's that friendship."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "明年要是再办这样的活动，咱们还去，当一回“大姐姐”。", "p": ["míng", "nián", "yào", "shi", "zài", "bàn", "zhè", "yàng", "de", "huó", "dòng", "", "zán", "men", "hái", "qù", "", "dāng", "yì", "huí", "", "dà", "jiě", "jiě", "", ""], "vi": "Năm sau nếu lại tổ chức hoạt động thế này, mình vẫn đi, làm một chuyến «chị lớn».", "en": "If they run something like this again next year, let's go and be \"big sisters\" once more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一言为定。到时候我把这些照片再翻出来给大家看。", "p": ["yī", "yán", "wéi", "dìng", "", "dào", "shí", "hòu", "wǒ", "bǎ", "zhè", "xiē", "zhào", "piān", "zài", "fān", "chū", "lái", "gěi", "dà", "jiā", "kàn", ""], "vi": "Được, nói trước đã. Lúc ấy mình sẽ lại lấy mấy tấm ảnh này ra cho mọi người xem.", "en": "It's a deal. When the time comes, I'll bring these photos out again to show everyone."}]}, {"n": 4, "zh": "短文：宿舍里的那一小时", "vi": "Đoạn văn: Một giờ trong ký túc xá", "en": "Passage: That one hour in the dorm", "kw": ["周围", "交", "丰富", "交流", "讨厌", "无聊", "却"], "lines": [{"s": "", "sp": [], "t": "我刚住进宿舍的时候，周围很安静，晚上只听得见楼下的车。那时我觉得日子有点儿无聊，也讨厌一个人吃饭。后来慢慢交了几个朋友，晚饭后大家坐在走廊里交流家乡的小吃和上课的笑话，晚上忽然变得丰富起来。可我却还给自己留出一小时：关上门，写写日记，听听自己喜欢的歌。有朋友在身边很好，有一段属于自己的时间，也同样重要。", "p": ["wǒ", "gāng", "zhù", "jìn", "sù", "shè", "de", "shí", "hòu", "", "zhōu", "wéi", "hěn", "ān", "jìng", "", "wǎn", "shàng", "zhǐ", "tīng", "de", "jiàn", "lóu", "xià", "de", "chē", "", "nà", "shí", "wǒ", "jué", "de", "rì", "zi", "yǒu", "diǎn", "r", "wú", "liáo", "", "yě", "tǎo", "yàn", "yí", "gè", "rén", "chī", "fàn", "", "hòu", "lái", "màn", "màn", "jiāo", "le", "jǐ", "gè", "péng", "you", "", "wǎn", "fàn", "hòu", "dà", "jiā", "zuò", "zài", "zǒu", "láng", "lǐ", "jiāo", "liú", "jiā", "xiāng", "de", "xiǎo", "chī", "hé", "shàng", "kè", "de", "xiào", "huà", "", "wǎn", "shàng", "hū", "rán", "biàn", "de", "fēng", "fù", "qǐ", "lái", "", "kě", "wǒ", "què", "huán", "gěi", "zì", "jǐ", "liú", "chū", "yì", "xiǎo", "shí", "", "guān", "shàng", "mén", "", "xiě", "xiě", "rì", "jì", "", "tīng", "tīng", "zì", "jǐ", "xǐ", "huān", "de", "gē", "", "yǒu", "péng", "you", "zài", "shēn", "biān", "hěn", "hǎo", "", "yǒu", "yí", "duàn", "shǔ", "yú", "zì", "jǐ", "de", "shí", "jiān", "", "yě", "tóng", "yàng", "zhòng", "yào", ""], "vi": "Lúc mới ở ký túc xá, xung quanh rất yên, tối chỉ nghe tiếng xe dưới phố. Khi ấy tôi thấy ngày tháng hơi buồn chán, cũng ghét phải ăn một mình. Sau dần kết được vài người bạn, sau bữa tối cả nhóm ngồi ở hành lang trao đổi về món quê và chuyện vui trên lớp, buổi tối bỗng trở nên phong phú. Thế nhưng tôi vẫn để dành cho mình một giờ: đóng cửa, viết nhật ký, nghe bài mình thích. Có bạn bên cạnh thì tốt, có một khoảng thời gian thuộc về mình cũng quan trọng không kém.", "en": "When I first moved into the dorm, it was very quiet around me; at night I could only hear the cars downstairs. In those days I found life a bit dull, and I also hated eating alone. Later I slowly made a few friends. After dinner we would sit in the corridor and talk about hometown snacks and jokes from class, and the evenings suddenly became rich. And yet I still keep one hour for myself: I close the door, write in my diary, and listen to a song I like. It is good to have friends nearby, and a stretch of time that belongs only to you is just as important."}]}, {"n": 5, "zh": "短文：朋友不是只会说好话的人", "vi": "Đoạn văn: Bạn không phải chỉ biết nói lời hay", "en": "Passage: A friend is not only someone who says nice things", "kw": ["镜子", "理解", "困难", "及时", "陪", "而", "真正"], "lines": [{"s": "", "sp": [], "t": "有人把朋友比作镜子，觉得镜子里只会看见自己最好看的样子。可我想，真正的朋友更像一扇窗。当你遇到困难，他能理解你为什么走不动，也会及时过来敲敲门，陪你把心里的话说完。他高兴时会和你一起笑，而在你不想说话的时候，也愿意安静地坐在旁边。这样的人不必很多，但有一个，就够让人觉得自己不是一个人。", "p": ["yǒu", "rén", "bǎ", "péng", "you", "bǐ", "zuò", "jìng", "zi", "", "jué", "de", "jìng", "zi", "lǐ", "zhǐ", "huì", "kàn", "jiàn", "zì", "jǐ", "zuì", "hǎo", "kàn", "de", "yàng", "zi", "", "kě", "wǒ", "xiǎng", "", "zhēn", "zhèng", "de", "péng", "you", "gèng", "xiàng", "yí", "shàn", "chuāng", "", "dāng", "nǐ", "yù", "dào", "kùn", "nán", "", "tā", "néng", "lǐ", "jiě", "nǐ", "wèi", "shén", "me", "zǒu", "bú", "dòng", "", "yě", "huì", "jí", "shí", "guò", "lái", "qiāo", "qiāo", "mén", "", "péi", "nǐ", "bǎ", "xīn", "lǐ", "de", "huà", "shuō", "wán", "", "tā", "gāo", "xìng", "shí", "huì", "hé", "nǐ", "yì", "qǐ", "xiào", "", "ér", "zài", "nǐ", "bù", "xiǎng", "shuō", "huà", "de", "shí", "hòu", "", "yě", "yuàn", "yì", "ān", "jìng", "dì", "zuò", "zài", "páng", "biān", "", "zhè", "yàng", "de", "rén", "bú", "bì", "hěn", "duō", "", "dàn", "yǒu", "yí", "gè", "", "jiù", "gòu", "ràng", "rén", "jué", "de", "zì", "jǐ", "bú", "shì", "yí", "gè", "rén", ""], "vi": "Có người ví bạn bè như tấm gương, cho rằng trong gương chỉ thấy mình ở kiểu đẹp nhất. Nhưng tôi nghĩ, người bạn thật sự hơn giống một ô cửa sổ. Khi bạn gặp khó khăn, người ấy hiểu vì sao bạn bước không nổi, cũng kịp thời đến gõ cửa, ở bên để bạn nói hết những điều trong lòng. Lúc vui họ cười cùng bạn, còn khi bạn không muốn nói, họ cũng sẵn sàng ngồi yên cạnh đó. Người như vậy không cần nhiều, nhưng có một người thôi, cũng đủ để thấy mình không cô độc.", "en": "Some people compare a friend to a mirror, and feel that a mirror only shows you at your best. But I think a true friend is more like a window. When you run into difficulties, they can understand why you can't go on, and they will also come and knock in time, and sit with you until you've said what's on your mind. They will laugh with you when they're happy, and when you don't feel like talking, they are also willing to sit quietly beside you. You don't need many people like that, but even one is enough to make you feel you are not alone."}]}]}, {"l": 3, "texts": [{"n": 1, "zh": "对话：阿玲面试前有点儿紧张", "vi": "Hội thoại: A Linh hơi hồi hộp trước buổi phỏng vấn", "en": "Dialogue: A Linh is a little nervous before her interview", "kw": ["紧张", "能力", "提供", "信心", "招聘", "挺"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "明天那家语言中心招聘辅导老师，你还去吗？", "p": ["míng", "tiān", "nà", "jiā", "yǔ", "yán", "zhōng", "xīn", "zhāo", "pìn", "fǔ", "dǎo", "lǎo", "shī", "", "nǐ", "hái", "qù", "ma", ""], "vi": "Ngày mai trung tâm ngôn ngữ ấy tuyển giáo viên kèm, cậu vẫn đi chứ?", "en": "That language centre is recruiting tutors tomorrow — are you still going?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "去。可我一想到要开口介绍自己，就有点儿紧张。", "p": ["qù", "", "kě", "wǒ", "yì", "xiǎng", "dào", "yào", "kāi", "kǒu", "jiè", "shào", "zì", "jǐ", "", "jiù", "yǒu", "diǎn", "r", "jǐn", "zhāng", ""], "vi": "Đi chứ. Nhưng nghĩ đến lúc phải mở miệng giới thiệu mình là mình hơi hồi hộp.", "en": "Yes. But as soon as I think about having to introduce myself, I get a little nervous."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "他们要看的是你的能力，不是你讲得漂不漂亮。你带学生复习，一向很清楚。", "p": ["tā", "men", "yào", "kàn", "de", "shì", "nǐ", "de", "néng", "lì", "", "bú", "shì", "nǐ", "jiǎng", "de", "piāo", "bú", "piào", "liàng", "", "nǐ", "dài", "xué", "shēng", "fù", "xí", "", "yí", "xiàng", "hěn", "qīng", "chǔ", ""], "vi": "Họ nhìn năng lực của cậu, không phải nói hay hay không. Cậu kèm các bạn ôn bài vốn rất rõ ràng.", "en": "They'll be looking at your ability, not at how pretty your speech is. You're always very clear when you review with students."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "通知上说，他们会提供一周的培训。有培训，我心里才有信心一点儿。", "p": ["tōng", "zhī", "shàng", "shuō", "", "tā", "men", "huì", "tí", "gōng", "yì", "zhōu", "de", "péi", "xùn", "", "yǒu", "péi", "xùn", "", "wǒ", "xīn", "lǐ", "cái", "yǒu", "xìn", "xīn", "yì", "diǎn", "r", ""], "vi": "Trong giấy báo nói họ sẽ cung cấp một tuần tập huấn. Có tập huấn, mình mới có chút tự tin.", "en": "The notice said they would provide a week of training. With that, I feel a bit more confident."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就好好睡一觉。我看你挺适合这份工作的。", "p": ["nà", "jiù", "hǎo", "hǎo", "shuì", "yí", "jiào", "", "wǒ", "kàn", "nǐ", "tǐng", "shì", "hé", "zhè", "fèn", "gōng", "zuò", "de", ""], "vi": "Vậy thì ngủ một giấc cho ngon. Mình thấy cậu khá hợp với việc này.", "en": "Then get a good night's sleep. I think you're quite right for this job."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。明天我一出来，就给你发消息。", "p": ["hǎo", "", "míng", "tiān", "wǒ", "yì", "chū", "lái", "", "jiù", "gěi", "nǐ", "fā", "xiāo", "xī", ""], "vi": "Được. Ngày mai ra xong mình nhắn ngay cho cậu.", "en": "All right. I'll message you as soon as I come out tomorrow."}]}, {"n": 2, "zh": "对话：周姐和阿玲谈两份应聘材料", "vi": "Hội thoại: Chị Châu và A Linh bàn hai hồ sơ ứng tuyển", "en": "Dialogue: Sister Zhou and A Linh discuss two applications", "kw": ["本来", "材料", "符合", "负责", "通知", "应聘"], "lines": [{"s": "周姐", "sp": ["zhōu", "jiě"], "t": "阿玲，你帮我看看这两份应聘材料。前台这份工作，本来我们想找有经验的人。", "p": ["ā", "líng", "", "nǐ", "bāng", "wǒ", "kàn", "kàn", "zhè", "liǎng", "fèn", "yìng", "pìn", "cái", "liào", "", "qián", "tái", "zhè", "fèn", "gōng", "zuò", "", "běn", "lái", "wǒ", "men", "xiǎng", "zhǎo", "yǒu", "jīng", "yàn", "de", "rén", ""], "vi": "A Linh, em xem giúp chị hai hồ sơ ứng tuyển này. Việc lễ tân này, vốn dĩ chị muốn tìm người có kinh nghiệm.", "en": "A Linh, help me look at these two job applications. For this front-desk job, we originally wanted someone with experience."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "这份更符合要求：字写得清楚，也写过类似的工作。那一份经验少一些。", "p": ["zhè", "fèn", "gèng", "fú", "hé", "yāo", "qiú", "", "zì", "xiě", "de", "qīng", "chǔ", "", "yě", "xiě", "guò", "lèi", "sì", "de", "gōng", "zuò", "", "nà", "yí", "fèn", "jīng", "yàn", "shǎo", "yì", "xiē", ""], "vi": "Hồ sơ này hợp yêu cầu hơn: chữ viết rõ, cũng từng làm việc tương tự. Hồ sơ kia ít kinh nghiệm hơn.", "en": "This one fits the requirements better: the writing is clear, and they've done similar work. The other one has a little less experience."}, {"s": "周姐", "sp": ["zhōu", "jiě"], "t": "那我先通知第一位下周三来见面。来了以后，前台就由她负责试做一天。", "p": ["nà", "wǒ", "xiān", "tōng", "zhī", "dì", "yī", "wèi", "xià", "zhōu", "sān", "lái", "jiàn", "miàn", "", "lái", "le", "yǐ", "hòu", "", "qián", "tái", "jiù", "yóu", "tā", "fù", "zé", "shì", "zuò", "yì", "tiān", ""], "vi": "Vậy chị báo trước cho người thứ nhất thứ tư tuần sau đến gặp. Đến rồi thì để bạn ấy phụ trách lễ tân thử một ngày.", "en": "Then I'll notify the first person to come in next Wednesday. Once they're here, they can be responsible for the front desk on a one-day trial."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "要是她那天来不了呢？", "p": ["yào", "shi", "tā", "nà", "tiān", "lái", "bù", "liǎo", "ne", ""], "vi": "Nếu hôm đó bạn ấy không đến được thì sao?", "en": "What if she can't come that day?"}, {"s": "周姐", "sp": ["zhōu", "jiě"], "t": "再联系第二位。招聘不宜拖太久，咱们尽快定下来。", "p": ["zài", "lián", "xì", "dì", "èr", "wèi", "", "zhāo", "pìn", "bù", "yí", "tuō", "tài", "jiǔ", "", "zán", "men", "jǐn", "kuài", "dìng", "xià", "lái", ""], "vi": "Thì liên lạc người thứ hai. Việc tuyển dụng không nên kéo dài, mình quyết sớm thôi.", "en": "Then we'll contact the second one. We shouldn't let the hiring drag on — let's decide as soon as we can."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好，我把时间记在本子上。", "p": ["hǎo", "", "wǒ", "bǎ", "shí", "jiān", "jì", "zài", "běn", "zi", "shàng", ""], "vi": "Được, em ghi thời gian vào sổ.", "en": "All right, I'll write the time down in the notebook."}]}, {"n": 3, "zh": "对话：陈晓跟阿玲说她的新工作", "vi": "Hội thoại: Trần Hiểu kể với A Linh về việc mới", "en": "Dialogue: Chen Xiao tells A Linh about her new job", "kw": ["安排", "另外", "律师", "收入", "咱们", "专业"], "lines": [{"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "阿玲，我找到工作了，在一家律师事务所做助理。", "p": ["ā", "líng", "", "wǒ", "zhǎo", "dào", "gōng", "zuò", "le", "", "zài", "yì", "jiā", "lǜ", "shī", "shì", "wù", "suǒ", "zuò", "zhù", "lǐ", ""], "vi": "A Linh, mình tìm được việc rồi, làm trợ lý ở một văn phòng luật sư.", "en": "A Linh, I've found a job — as an assistant at a law firm."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "真好！你的专业就是法律，这不是正好用上了吗？", "p": ["zhēn", "hǎo", "", "nǐ", "de", "zhuān", "yè", "jiù", "shì", "fǎ", "lǜ", "", "zhè", "bú", "shì", "zhèng", "hǎo", "yòng", "shàng", "le", "ma", ""], "vi": "Hay quá! Chuyên ngành cậu là luật, thế thì chẳng đúng lúc dùng được sao?", "en": "That's wonderful! Your major is law — isn't that just the right use for it?"}, {"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "对。收入不算特别高，可每个月都很稳定。另外，晚上还能继续上课。", "p": ["duì", "", "shōu", "rù", "bú", "suàn", "tè", "bié", "gāo", "", "kě", "měi", "gè", "yuè", "dōu", "hěn", "wěn", "dìng", "", "lìng", "wài", "", "wǎn", "shàng", "hái", "néng", "jì", "xù", "shàng", "kè", ""], "vi": "Đúng. Thu nhập không đặc biệt cao, nhưng tháng nào cũng ổn định. Ngoài ra, tối vẫn học tiếp được.", "en": "Yes. The income isn't especially high, but it's steady every month. Besides that, I can still go to class in the evenings."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那时间够用吗？咱们以前晚上常一起去图书馆。", "p": ["nà", "shí", "jiān", "gòu", "yòng", "ma", "", "zán", "men", "yǐ", "qián", "wǎn", "shàng", "cháng", "yì", "qǐ", "qù", "tú", "shū", "guǎn", ""], "vi": "Vậy thời gian có đủ không? Trước giờ tối nào mình cũng hay cùng đi thư viện.", "en": "Will you have enough time? We used to go to the library together in the evenings."}, {"s": "陈晓", "sp": ["chén", "xiǎo"], "t": "我自己先把一周的安排写好。忙的那几天，可能只能周末再见了。", "p": ["wǒ", "zì", "jǐ", "xiān", "bǎ", "yì", "zhōu", "de", "ān", "pái", "xiě", "hǎo", "", "máng", "de", "nà", "jǐ", "tiān", "", "kě", "néng", "zhǐ", "néng", "zhōu", "mò", "zài", "jiàn", "le", ""], "vi": "Mình sẽ viết sẵn lịch một tuần. Những ngày bận, có lẽ chỉ cuối tuần mới gặp được.", "en": "I'll write out the week's schedule first. On the busy days, we may only be able to meet at the weekend."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没关系。你先安顿好，我为你高兴。", "p": ["méi", "guān", "xì", "", "nǐ", "xiān", "ān", "dùn", "hǎo", "", "wǒ", "wèi", "nǐ", "gāo", "xìng", ""], "vi": "Không sao. Cậu an vị đã, mình mừng cho cậu.", "en": "That's all right. Get yourself settled first — I'm happy for you."}]}, {"n": 4, "zh": "短文：面试时我想着的两件事", "vi": "Đoạn văn: Hai điều tôi nhớ khi phỏng vấn", "en": "Passage: Two things I keep in mind in an interview", "kw": ["首先", "其次", "诚实", "正式", "留"], "lines": [{"s": "", "sp": [], "t": "第一次去参加正式面试的时候，我在门口站了很久。后来我只记住两件事。首先，要诚实：不会的不要装会，被问到也可以说“我想再学”。其次，要认真听完再回答，不要抢话。衣服不必很贵，但要干净、整齐。走出门的时候我还是有些不好意思，可我希望自己至少留下了一个清楚、认真的印象。", "p": ["dì", "yī", "cì", "qù", "cān", "jiā", "zhèng", "shì", "miàn", "shì", "de", "shí", "hòu", "", "wǒ", "zài", "mén", "kǒu", "zhàn", "le", "hěn", "jiǔ", "", "hòu", "lái", "wǒ", "zhǐ", "jì", "zhù", "liǎng", "jiàn", "shì", "", "shǒu", "xiān", "", "yào", "chéng", "shí", "", "bú", "huì", "de", "bú", "yào", "zhuāng", "huì", "", "bèi", "wèn", "dào", "yě", "kě", "yǐ", "shuō", "", "wǒ", "xiǎng", "zài", "xué", "", "", "qí", "cì", "", "yào", "rèn", "zhēn", "tīng", "wán", "zài", "huí", "dá", "", "bú", "yào", "qiǎng", "huà", "", "yī", "fú", "bú", "bì", "hěn", "guì", "", "dàn", "yào", "gān", "jìng", "", "zhěng", "qí", "", "zǒu", "chū", "mén", "de", "shí", "hòu", "wǒ", "hái", "shì", "yǒu", "xiē", "bù", "hǎo", "yì", "sī", "", "kě", "wǒ", "xī", "wàng", "zì", "jǐ", "zhì", "shǎo", "liú", "xià", "le", "yí", "gè", "qīng", "chǔ", "", "rèn", "zhēn", "de", "yìn", "xiàng", ""], "vi": "Lần đầu đi phỏng vấn chính thức, tôi đứng mãi ở cửa. Sau đó tôi chỉ nhớ hai điều. Trước hết, phải thành thật: không biết thì đừng giả vờ biết, bị hỏi cũng có thể nói «tôi muốn học thêm». Thứ hai, phải nghe hết rồi mới trả lời, đừng cướp lời. Áo quần không cần đắt, nhưng phải sạch và gọn. Lúc bước ra tôi vẫn hơi ngại, nhưng mong ít nhất mình đã để lại một ấn tượng rõ ràng, nghiêm túc.", "en": "The first time I went to a formal interview, I stood at the door for a long time. After that I only kept two things in mind. First, be honest: if you can't do something, don't pretend you can, and if you're asked, you can also say \"I'd like to learn more.\" Second, listen to the end before you answer, and don't interrupt. Your clothes don't have to be expensive, but they should be clean and tidy. I was still a little embarrassed when I walked out, but I hoped I had at least left a clear, careful impression."}]}, {"n": 5, "zh": "短文：把约定的时间放在心里", "vi": "Đoạn văn: Để thời gian đã hẹn trong lòng", "en": "Passage: Keep the appointed time in mind", "kw": ["不管", "改变", "感觉", "顾客", "判断", "约会", "准时", "与"], "lines": [{"s": "", "sp": [], "t": "我在一家小咖啡馆打工。每天要与顾客说话，先判断他们是想坐一坐，还是打包就走，再按他们的需要去做。不管店里有多忙，我都提醒自己不要改变脸上的态度。有一次，一位老师与我约好下午三点来取蛋糕，那是我们的一次约会。我提前做好，准时放到柜台上。她进门时笑着说：“我就知道你们不会让人白等。”那句话让我感觉，准时其实是一种尊重。", "p": ["wǒ", "zài", "yì", "jiā", "xiǎo", "kā", "fēi", "guǎn", "dǎ", "gōng", "", "měi", "tiān", "yào", "yǔ", "gù", "kè", "shuō", "huà", "", "xiān", "pàn", "duàn", "tā", "men", "shì", "xiǎng", "zuò", "yí", "zuò", "", "hái", "shì", "dǎ", "bāo", "jiù", "zǒu", "", "zài", "àn", "tā", "men", "de", "xū", "yào", "qù", "zuò", "", "bù", "guǎn", "diàn", "lǐ", "yǒu", "duō", "máng", "", "wǒ", "dōu", "tí", "xǐng", "zì", "jǐ", "bú", "yào", "gǎi", "biàn", "liǎn", "shàng", "de", "tài", "dù", "", "yǒu", "yí", "cì", "", "yí", "wèi", "lǎo", "shī", "yǔ", "wǒ", "yuē", "hǎo", "xià", "wǔ", "sān", "diǎn", "lái", "qǔ", "dàn", "gāo", "", "nà", "shì", "wǒ", "men", "de", "yí", "cì", "yuē", "huì", "", "wǒ", "tí", "qián", "zuò", "hǎo", "", "zhǔn", "shí", "fàng", "dào", "guì", "tái", "shàng", "", "tā", "jìn", "mén", "shí", "xiào", "zhe", "shuō", "", "", "wǒ", "jiù", "zhī", "dào", "nǐ", "men", "bú", "huì", "ràng", "rén", "bái", "děng", "", "", "nà", "jù", "huà", "ràng", "wǒ", "gǎn", "jué", "", "zhǔn", "shí", "qí", "shí", "shì", "yì", "zhǒng", "zūn", "zhòng", ""], "vi": "Tôi làm thêm ở một quán cà phê nhỏ. Mỗi ngày phải nói chuyện với khách, trước hết phán đoán họ muốn ngồi một lúc hay lấy mang về, rồi làm theo nhu cầu của họ. Dù trong quán bận đến mấy, tôi cũng nhắc mình đừng đổi thái độ trên mặt. Có lần một cô giáo hẹn với tôi chiều ba giờ đến lấy bánh, đó là một cuộc hẹn của chúng tôi. Tôi làm sẵn, đúng giờ đặt lên quầy. Cô bước vào, cười nói: «Tôi biết các bạn sẽ không để người ta đợi phí.» Câu ấy khiến tôi cảm thấy, đúng giờ thật ra là một cách tôn trọng.", "en": "I work part-time in a little café. Every day I have to talk with the customers, first judge whether they want to sit for a while or take their order away, and then do what they need. No matter how busy the shop is, I remind myself not to change the look on my face. Once a teacher arranged with me to pick up a cake at three in the afternoon — that was an appointment we had. I had it ready and put it on the counter on time. When she came in she smiled and said, \"I knew you wouldn't leave anyone waiting for nothing.\" That sentence made me feel that being on time is really a kind of respect."}]}]}, {"l": 4, "texts": [{"n": 1, "zh": "对话：小雪又想换工作", "vi": "Hội thoại: Tiểu Tuyết lại muốn đổi việc", "en": "Dialogue: Xiaoxue wants to change jobs again", "kw": ["完全", "以为", "份", "提", "赚"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，我又想提换工作的事了。这份工作做了半年，我以为能学到很多，结果每天都差不多。", "p": ["ā", "líng", "", "wǒ", "yòu", "xiǎng", "tí", "huàn", "gōng", "zuò", "de", "shì", "le", "", "zhè", "fèn", "gōng", "zuò", "zuò", "le", "bàn", "nián", "", "wǒ", "yǐ", "wéi", "néng", "xué", "dào", "hěn", "duō", "", "jié", "guǒ", "měi", "tiān", "dōu", "chà", "bu", "duō", ""], "vi": "A Linh, mình lại muốn nêu chuyện đổi việc. Việc này làm đã nửa năm, mình tưởng học được nhiều, hóa ra ngày nào cũng gần như nhau.", "en": "A Linh, I want to bring up changing jobs again. I've done this job for half a year. I thought I would learn a lot, but every day is more or less the same."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "你不是才涨了一点儿工资吗？别完全否定它。", "p": ["nǐ", "bú", "shì", "cái", "zhǎng", "le", "yì", "diǎn", "r", "gōng", "zī", "ma", "", "bié", "wán", "quán", "fǒu", "dìng", "tā", ""], "vi": "Chẳng phải cậu vừa được tăng một chút lương sao? Đừng phủ nhận hoàn toàn.", "en": "Didn't you just get a small raise? Don't dismiss it completely."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "涨是涨了，可我看同学做别的，好像赚得更多。", "p": ["zhǎng", "shì", "zhǎng", "le", "", "kě", "wǒ", "kàn", "tóng", "xué", "zuò", "bié", "de", "", "hǎo", "xiàng", "zuàn", "de", "gèng", "duō", ""], "vi": "Tăng thì có tăng, nhưng mình thấy bạn cùng lớp làm việc khác, hình như kiếm được nhiều hơn.", "en": "The raise happened, yes, but I see classmates in other jobs who seem to earn more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "赚钱很重要，可一份工作好不好，不能只看这个月的数字。", "p": ["zhuàn", "qián", "hěn", "zhòng", "yào", "", "kě", "yí", "fèn", "gōng", "zuò", "hǎo", "bù", "hǎo", "", "bù", "néng", "zhǐ", "kàn", "zhè", "ge", "yuè", "de", "shù", "zì", ""], "vi": "Kiếm tiền thì quan trọng, nhưng một công việc có tốt hay không không thể chỉ nhìn con số tháng này.", "en": "Earning money is important, but whether a job is good or not can't be judged only by this month's number."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那你说我该等等？", "p": ["nà", "nǐ", "shuō", "wǒ", "gāi", "děng", "děng", ""], "vi": "Vậy cậu bảo mình nên đợi thêm?", "en": "So you think I should wait a little longer?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先把现在手边的事做好。真要走，也先想清楚下一份是什么，再提离开。", "p": ["xiān", "bǎ", "xiàn", "zài", "shǒu", "biān", "de", "shì", "zuò", "hǎo", "", "zhēn", "yào", "zǒu", "", "yě", "xiān", "xiǎng", "qīng", "chǔ", "xià", "yí", "fèn", "shì", "shén", "me", "", "zài", "tí", "lí", "kāi", ""], "vi": "Hãy làm tốt việc đang có đã. Thật sự muốn đi, cũng nghĩ rõ việc tiếp theo là gì rồi hãy nói đến chuyện rời đi.", "en": "Do the work in front of you well first. If you really want to leave, think clearly about what the next job is before you bring up going."}]}, {"n": 2, "zh": "对话：林主管请小雪把调查提前做完", "vi": "Hội thoại: Chủ quản Lâm nhờ Tiểu Tuyết hoàn thành khảo sát sớm", "en": "Dialogue: Supervisor Lin asks Xiaoxue to finish a survey early", "kw": ["保证", "调查", "计划", "提前", "提醒", "原来", "乱"], "lines": [{"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "小雪，上周那份调查，计划是这周五交。现在要提前到周三，你能保证完成吗？", "p": ["xiǎo", "xuě", "", "shàng", "zhōu", "nà", "fèn", "diào", "chá", "", "jì", "huà", "shì", "zhè", "zhōu", "wǔ", "jiāo", "", "xiàn", "zài", "yào", "tí", "qián", "dào", "zhōu", "sān", "", "nǐ", "néng", "bǎo", "zhèng", "wán", "chéng", "ma", ""], "vi": "Tiểu Tuyết, bản khảo sát tuần trước, kế hoạch là nộp thứ sáu này. Giờ phải làm sớm hơn vào thứ tư, em bảo đảm hoàn thành được không?", "en": "Xiaoxue, for that survey from last week, the plan was to hand it in this Friday. Now it has to be earlier, by Wednesday — can you guarantee you'll finish it?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周三……时间是紧了些。我先把这几天的安排重新看一遍，免得改乱了。", "p": ["zhōu", "sān", "", "", "shí", "jiān", "shì", "jǐn", "le", "xiē", "", "wǒ", "xiān", "bǎ", "zhè", "jǐ", "tiān", "de", "ān", "pái", "chóng", "xīn", "kàn", "yí", "biàn", "", "miǎn", "de", "gǎi", "luàn", "le", ""], "vi": "Thứ tư… thời gian hơi căng. Em xem lại lịch mấy ngày này đã, để khỏi sửa cho rối.", "en": "Wednesday… that's a bit tight. I'll go through these days' schedule again first, so it doesn't get into a mess."}, {"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "原来截止日期改了，是因为后面还有一场会。我明天再提醒你一次。", "p": ["yuán", "lái", "jié", "zhǐ", "rì", "qī", "gǎi", "le", "", "shì", "yīn", "wèi", "hòu", "miàn", "hái", "yǒu", "yì", "cháng", "huì", "", "wǒ", "míng", "tiān", "zài", "tí", "xǐng", "nǐ", "yí", "cì", ""], "vi": "Hóa ra hạn chót đổi vì phía sau còn một cuộc họp. Ngày mai chị nhắc em thêm lần nữa.", "en": "It turns out the deadline was changed because there's a meeting after that. I'll remind you again tomorrow."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好。今晚我先做完前半部分，明天一早就把后半部分接着做。", "p": ["hǎo", "", "jīn", "wǎn", "wǒ", "xiān", "zuò", "wán", "qián", "bàn", "bù", "fèn", "", "míng", "tiān", "yì", "zǎo", "jiù", "bǎ", "hòu", "bàn", "bù", "fèn", "jiē", "zhe", "zuò", ""], "vi": "Được. Tối nay em làm xong nửa đầu, sáng mai làm tiếp nửa sau.", "en": "All right. I'll finish the first half tonight, and carry on with the second half first thing tomorrow."}, {"s": "林主管", "sp": ["lín", "zhǔ", "guǎn"], "t": "有困难早点说，不要拖到最后。", "p": ["yǒu", "kùn", "nán", "zǎo", "diǎn", "shuō", "", "bú", "yào", "tuō", "dào", "zuì", "hòu", ""], "vi": "Có khó thì nói sớm, đừng để đến phút cuối.", "en": "If there's a difficulty, say so early — don't leave it until the last minute."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "知道了。我尽量在周二晚上给您。", "p": ["zhī", "dào", "le", "", "wǒ", "jǐn", "liàng", "zài", "zhōu", "èr", "wǎn", "shàng", "gěi", "nín", ""], "vi": "Em biết rồi. Em cố đưa chị vào tối thứ ba.", "en": "Understood. I'll try to get it to you by Tuesday evening."}]}, {"n": 3, "zh": "对话：赵叔叔跟阿玲谈做小生意", "vi": "Hội thoại: Chú Triệu nói với A Linh về làm ăn nhỏ", "en": "Dialogue: Uncle Zhao talks with A Linh about a small business", "kw": ["积累", "经验", "生意", "一切", "谈"], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "赵叔叔，听说您在社区开了一家小文具店？", "p": ["zhào", "shū", "shu", "", "tīng", "shuō", "nín", "zài", "shè", "qū", "kāi", "le", "yì", "jiā", "xiǎo", "wén", "jù", "diàn", ""], "vi": "Chú Triệu, nghe nói chú mở một tiệm văn phòng phẩm nhỏ trong khu?", "en": "Uncle Zhao, I heard you opened a little stationery shop in the neighbourhood?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "是啊。说起来是生意，其实刚开头那几个月，一切都比我想的慢。", "p": ["shì", "a", "", "shuō", "qǐ", "lái", "shì", "shēng", "yì", "", "qí", "shí", "gāng", "kāi", "tóu", "nà", "jǐ", "gè", "yuè", "", "yí", "qiè", "dōu", "bǐ", "wǒ", "xiǎng", "de", "màn", ""], "vi": "Phải. Nói là làm ăn, nhưng mấy tháng đầu mọi thứ đều chậm hơn chú nghĩ.", "en": "That's right. You can call it a business, but in those first few months everything was slower than I had expected."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "您以前不是做过老师吗？开店跟教书差很多吧？", "p": ["nín", "yǐ", "qián", "bú", "shì", "zuò", "guò", "lǎo", "shī", "ma", "", "kāi", "diàn", "gēn", "jiāo", "shū", "chà", "hěn", "duō", "ba", ""], "vi": "Trước chú chẳng phải làm giáo viên sao? Mở tiệm khác dạy học nhiều chứ?", "en": "Weren't you a teacher before? Running a shop must be very different from teaching, surely?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "差很多。不过以前带学生，也让我积累了一些与人谈话的经验。客人来谈需要，我能听得比较耐心。", "p": ["chà", "hěn", "duō", "", "bú", "guò", "yǐ", "qián", "dài", "xué", "shēng", "", "yě", "ràng", "wǒ", "jī", "lěi", "le", "yì", "xiē", "yǔ", "rén", "tán", "huà", "de", "jīng", "yàn", "", "kè", "rén", "lái", "tán", "xū", "yào", "", "wǒ", "néng", "tīng", "de", "bǐ", "jiào", "nài", "xīn", ""], "vi": "Khác nhiều. Nhưng trước dẫn học sinh cũng giúp chú tích lũy ít kinh nghiệm nói chuyện với người. Khách đến bàn nhu cầu, chú nghe được kiên nhẫn hơn.", "en": "Very different. But taking students before also helped me build up some experience of talking with people. When customers come to discuss what they need, I can listen more patiently."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "那现在好一些了吗？", "p": ["nà", "xiàn", "zài", "hǎo", "yì", "xiē", "le", "ma", ""], "vi": "Vậy giờ đã khá hơn chưa?", "en": "Is it any better now?"}, {"s": "赵叔叔", "sp": ["zhào", "shū", "shu"], "t": "慢慢好了。别急着看这个月赚多少，先把店里的事一件一件做稳。", "p": ["màn", "màn", "hǎo", "le", "", "bié", "jí", "zhe", "kàn", "zhè", "ge", "yuè", "zhuàn", "duō", "shǎo", "", "xiān", "bǎ", "diàn", "lǐ", "de", "shì", "yí", "jiàn", "yí", "jiàn", "zuò", "wěn", ""], "vi": "Dần khá rồi. Đừng vội nhìn tháng này kiếm được bao nhiêu, hãy làm vững từng việc trong tiệm đã.", "en": "It's slowly getting better. Don't be in a hurry to look at how much this month earns — first get each thing in the shop on a steady footing."}]}, {"n": 4, "zh": "短文：一条让人放心的消息", "vi": "Đoạn văn: Một tin khiến người ta yên tâm", "en": "Passage: A piece of news that puts people at ease", "kw": ["按时", "按照", "成功", "感谢", "奖金", "顺利", "消息"], "lines": [{"s": "", "sp": [], "t": "今年部门的工作进行得很顺利。大家按照年初写好的计划，一件一件按时做完，最后成功地赶上了大活动的日期。活动结束那天，经理发来一条消息，感谢每一个加班的人，还说今年会有一笔小小的奖金。钱不多，可那条消息让人觉得：只要把该做的事做完，别人是看得见的。", "p": ["jīn", "nián", "bù", "mén", "de", "gōng", "zuò", "jìn", "xíng", "de", "hěn", "shùn", "lì", "", "dà", "jiā", "àn", "zhào", "nián", "chū", "xiě", "hǎo", "de", "jì", "huà", "", "yí", "jiàn", "yí", "jiàn", "àn", "shí", "zuò", "wán", "", "zuì", "hòu", "chéng", "gōng", "dì", "gǎn", "shàng", "le", "dà", "huó", "dòng", "de", "rì", "qī", "", "huó", "dòng", "jié", "shù", "nà", "tiān", "", "jīng", "lǐ", "fà", "lái", "yì", "tiáo", "xiāo", "xī", "", "gǎn", "xiè", "měi", "yí", "gè", "jiā", "bān", "de", "rén", "", "hái", "shuō", "jīn", "nián", "huì", "yǒu", "yì", "bǐ", "xiǎo", "xiǎo", "de", "jiǎng", "jīn", "", "qián", "bù", "duō", "", "kě", "nà", "tiáo", "xiāo", "xī", "ràng", "rén", "jué", "de", "", "zhǐ", "yào", "bǎ", "gāi", "zuò", "de", "shì", "zuò", "wán", "", "bié", "rén", "shì", "kàn", "de", "jiàn", "de", ""], "vi": "Năm nay việc của phòng diễn ra rất thuận lợi. Mọi người làm theo kế hoạch viết từ đầu năm, hoàn thành đúng hạn từng việc, cuối cùng thành công bắt kịp ngày sự kiện lớn. Ngày kết thúc, giám đốc gửi một tin, cảm ơn từng người tăng ca, còn nói năm nay sẽ có một khoản thưởng nhỏ. Tiền không nhiều, nhưng tin ấy khiến người ta thấy: chỉ cần làm xong việc phải làm, người khác sẽ nhìn thấy.", "en": "This year the department's work has gone smoothly. Everyone followed the plan written at the beginning of the year, finished each task on time, and in the end succeeded in meeting the date of the big event. On the day it ended, the manager sent a message thanking everyone who had worked extra hours, and also said there would be a small bonus this year. It was not a lot of money, but that message made people feel that if you finish what you're supposed to do, others will notice."}]}, {"n": 5, "zh": "短文：不愿做的那份工作", "vi": "Đoạn văn: Việc mình không muốn làm", "en": "Passage: The work you would rather not do", "kw": ["不得不", "方法", "工资", "甚至", "责任", "知识"], "lines": [{"s": "", "sp": [], "t": "工作里总会有人不愿意做的事：又慢，又看不出成绩。可有时你不得不把它做完，因为那是你的责任。我曾经把一份很烦的材料推了又推，甚至想：这又不会加工资，为什么要认真？后来还是坐下来，找到自己的方法，把材料一项一项做清楚。做完以后我才发现，自己又多懂了一点相关的知识。工资是生活的一部分，但把一件难事做完，也会让人踏实。", "p": ["gōng", "zuò", "lǐ", "zǒng", "huì", "yǒu", "rén", "bú", "yuàn", "yì", "zuò", "de", "shì", "", "yòu", "màn", "", "yòu", "kàn", "bù", "chū", "chéng", "jì", "", "kě", "yǒu", "shí", "nǐ", "bù", "de", "bù", "bǎ", "tā", "zuò", "wán", "", "yīn", "wèi", "nà", "shì", "nǐ", "de", "zé", "rèn", "", "wǒ", "céng", "jīng", "bǎ", "yí", "fèn", "hěn", "fán", "de", "cái", "liào", "tuī", "le", "yòu", "tuī", "", "shèn", "zhì", "xiǎng", "", "zhè", "yòu", "bú", "huì", "jiā", "gōng", "zī", "", "wèi", "shén", "me", "yào", "rèn", "zhēn", "", "hòu", "lái", "hái", "shì", "zuò", "xià", "lái", "", "zhǎo", "dào", "zì", "jǐ", "de", "fāng", "fǎ", "", "bǎ", "cái", "liào", "yí", "xiàng", "yí", "xiàng", "zuò", "qīng", "chǔ", "", "zuò", "wán", "yǐ", "hòu", "wǒ", "cái", "fā", "xiàn", "", "zì", "jǐ", "yòu", "duō", "dǒng", "le", "yì", "diǎn", "xiāng", "guān", "de", "zhī", "shí", "", "gōng", "zī", "shì", "shēng", "huó", "de", "yí", "bù", "fèn", "", "dàn", "bǎ", "yí", "jiàn", "nán", "shì", "zuò", "wán", "", "yě", "huì", "ràng", "rén", "tā", "shi", ""], "vi": "Trong việc luôn có chuyện người ta không muốn làm: vừa chậm, vừa không thấy thành tích. Nhưng đôi khi bạn buộc phải làm xong, vì đó là trách nhiệm. Tôi từng đẩy đi đẩy lại một bản tài liệu rất mệt, thậm chí nghĩ: cái này lại không tăng lương, cần gì nghiêm túc? Sau cùng vẫn ngồi xuống, tìm phương pháp của mình, làm rõ từng mục. Xong rồi tôi mới thấy mình hiểu thêm một chút kiến thức liên quan. Lương là một phần của đời sống, nhưng làm xong một việc khó cũng khiến người ta vững lòng.", "en": "In any job there are always things people would rather not do: they are slow, and they don't seem to show any results. But sometimes you have no choice but to finish them, because that is your responsibility. I once pushed a very tedious set of materials aside again and again, and even thought: this won't even raise my pay, so why take it seriously? In the end I still sat down, found my own method, and worked through the materials item by item. Only when I had finished did I realise I had learned a little more of the related knowledge. Pay is part of life, but finishing a hard task also leaves you feeling steady."}]}]}, {"l": 5, "texts": [{"n": 1, "zh": "对话：阿玲在家具店看沙发", "vi": "Hội thoại: A Linh xem ghế sofa ở cửa hàng nội thất", "en": "Dialogue: A Linh looks at sofas in a furniture shop", "kw": ["打折", "家具", "价格", "肯定", "流行", "沙发", "质量"], "lines": [{"s": "吴姐", "sp": ["wú", "jiě"], "t": "姑娘，想看沙发吗？这几款最近很流行，这周末还打折。", "p": ["gū", "niáng", "", "xiǎng", "kàn", "shā", "fā", "ma", "", "zhè", "jǐ", "kuǎn", "zuì", "jìn", "hěn", "liú", "xíng", "", "zhè", "zhōu", "mò", "hái", "dǎ", "zhé", ""], "vi": "Cô gái, muốn xem sofa không? Mấy mẫu này gần đây rất thịnh hành, cuối tuần này còn giảm giá.", "en": "Miss, would you like to look at sofas? These styles have been very popular lately, and they're also on sale this weekend."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想看质量好一点儿的。颜色不要太花，价格也希望能接受。", "p": ["wǒ", "xiǎng", "kàn", "zhì", "liàng", "hǎo", "yì", "diǎn", "r", "de", "", "yán", "sè", "bú", "yào", "tài", "huā", "", "jià", "gé", "yě", "xī", "wàng", "néng", "jiē", "shòu", ""], "vi": "Em muốn xem loại chất lượng khá hơn một chút. Màu đừng quá sặc sỡ, giá cũng mong chấp nhận được.", "en": "I'd like to see ones with a bit better quality. The colour shouldn't be too busy, and I hope the price is acceptable too."}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "那您看这一套。面料耐用，坐上去也舒服。现在的价格比上周低了不少。", "p": ["nà", "nín", "kàn", "zhè", "yí", "tào", "", "miàn", "liào", "nài", "yòng", "", "zuò", "shàng", "qù", "yě", "shū", "fú", "", "xiàn", "zài", "de", "jià", "gé", "bǐ", "shàng", "zhōu", "dī", "le", "bù", "shǎo", ""], "vi": "Vậy cô xem bộ này. Vải bền, ngồi cũng êm. Giá hiện tại thấp hơn tuần trước nhiều.", "en": "Then have a look at this set. The fabric is durable, and it's comfortable to sit on. The price now is quite a bit lower than last week."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我再摸摸。买家具不是小事，我肯定要再比较一下。", "p": ["wǒ", "zài", "mō", "mō", "", "mǎi", "jiā", "jù", "bú", "shì", "xiǎo", "shì", "", "wǒ", "kěn", "dìng", "yào", "zài", "bǐ", "jiào", "yí", "xià", ""], "vi": "Em sờ thêm đã. Mua nội thất không phải việc nhỏ, em chắc chắn phải so nữa.", "en": "I'll feel it again. Buying furniture isn't a small thing — I definitely want to compare a bit more."}, {"s": "吴姐", "sp": ["wú", "jiě"], "t": "可以。您先拍个照片，想好了再来。", "p": ["kě", "yǐ", "", "nín", "xiān", "pāi", "gè", "zhào", "piān", "", "xiǎng", "hǎo", "le", "zài", "lái", ""], "vi": "Được. Cô chụp ảnh trước, nghĩ xong hãy đến.", "en": "Of course. Take a photo first, and come back when you've thought it over."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好，谢谢您。我今天先看看别的店。", "p": ["hǎo", "", "xiè", "xiè", "nín", "", "wǒ", "jīn", "tiān", "xiān", "kàn", "kàn", "bié", "de", "diàn", ""], "vi": "Vâng, cảm ơn chị. Hôm nay em xem thêm vài cửa khác đã.", "en": "Thank you. I'll look at a few other shops today first."}]}, {"n": 2, "zh": "对话：阿玲和周南在商场", "vi": "Hội thoại: A Linh và Châu Nam ở trung tâm thương mại", "en": "Dialogue: A Linh and Zhou Nan at the mall", "kw": ["实在", "顺便", "现金", "效果", "光", "台"], "lines": [{"s": "周南", "sp": ["zhōu", "nán"], "t": "你不是来看台灯的吗？怎么站在冰箱前面了？", "p": ["nǐ", "bú", "shì", "lái", "kàn", "tái", "dēng", "de", "ma", "", "zěn", "me", "zhàn", "zài", "bīng", "xiāng", "qián", "miàn", "le", ""], "vi": "Chẳng phải cậu đến xem đèn bàn sao? Sao lại đứng trước tủ lạnh?", "en": "Weren't you here to look at desk lamps? Why are you standing in front of the fridges?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想顺便看看。这一台能耗低，可价钱实在不便宜。", "p": ["wǒ", "xiǎng", "shùn", "biàn", "kàn", "kàn", "", "zhè", "yì", "tái", "néng", "hào", "dī", "", "kě", "jià", "qián", "shí", "zài", "bú", "biàn", "yí", ""], "vi": "Mình muốn tiện thể xem. Cái này tiêu hao điện thấp, nhưng giá thực sự không rẻ.", "en": "I wanted to have a look while we're here. This one uses little electricity, but the price really isn't cheap."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "你不能光看宣传上写的效果，最好再问问一个月大概要用多少电。", "p": ["nǐ", "bù", "néng", "guāng", "kàn", "xuān", "chuán", "shàng", "xiě", "de", "xiào", "guǒ", "", "zuì", "hǎo", "zài", "wèn", "wèn", "yí", "gè", "yuè", "dà", "gài", "yào", "yòng", "duō", "shǎo", "diàn", ""], "vi": "Cậu đừng chỉ nhìn hiệu quả viết trên tờ quảng cáo, tốt nhất hỏi thêm mỗi tháng tốn khoảng bao nhiêu điện.", "en": "You shouldn't only look at the results written in the ads. It'd be better to ask how much electricity it uses in a month."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "说得对。那台灯呢？我想找一盏光不会太刺眼的。", "p": ["shuō", "de", "duì", "", "nà", "tái", "dēng", "ne", "", "wǒ", "xiǎng", "zhǎo", "yì", "zhǎn", "guāng", "bú", "huì", "tài", "cì", "yǎn", "de", ""], "vi": "Đúng đó. Còn đèn bàn? Mình muốn tìm cái ánh sáng không quá chói.", "en": "That's true. And the lamp? I want one whose light isn't too harsh."}, {"s": "周南", "sp": ["zhōu", "nán"], "t": "那两台都不错。你要是决定买，我可以用现金先付。", "p": ["nà", "liǎng", "tái", "dōu", "bú", "cuò", "", "nǐ", "yào", "shi", "jué", "dìng", "mǎi", "", "wǒ", "kě", "yǐ", "yòng", "xiàn", "jīn", "xiān", "fù", ""], "vi": "Hai cái kia cũng ổn. Nếu cậu quyết mua, mình có thể trả bằng tiền mặt trước.", "en": "Those two are both fine. If you decide to buy one, I can pay in cash first."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "先把说明书拍下来，回去再想一晚吧。", "p": ["xiān", "bǎ", "shuō", "míng", "shū", "pāi", "xià", "lái", "", "huí", "qù", "zài", "xiǎng", "yì", "wǎn", "ba", ""], "vi": "Chụp hướng dẫn đã, về nghĩ thêm một đêm.", "en": "Let's photograph the instructions first and think it over for a night at home."}]}, {"n": 3, "zh": "对话：给陈老师挑一份礼物", "vi": "Hội thoại: Chọn quà cho cô Trần", "en": "Dialogue: Choosing a gift for Teacher Chen", "kw": ["广告", "葡萄", "实际", "味道", "邀请", "艺术", "优点"], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "周末想邀请陈老师来家里吃晚饭。礼物你说买什么好？", "p": ["zhōu", "mò", "xiǎng", "yāo", "qǐng", "chén", "lǎo", "shī", "lái", "jiā", "lǐ", "chī", "wǎn", "fàn", "", "lǐ", "wù", "nǐ", "shuō", "mǎi", "shén", "me", "hǎo", ""], "vi": "Cuối tuần muốn mời cô Trần đến nhà ăn tối. Quà cậu bảo nên mua gì?", "en": "I'd like to invite Teacher Chen home for dinner at the weekend. What do you think we should buy her as a gift?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "水果比较合适。那边在卖葡萄，广告上写“又甜又大”，可不知道实际味道怎么样。", "p": ["shuǐ", "guǒ", "bǐ", "jiào", "hé", "shì", "", "nà", "biān", "zài", "mài", "pú", "tao", "", "guǎng", "gào", "shàng", "xiě", "", "yòu", "tián", "yòu", "dà", "", "", "kě", "bù", "zhī", "dào", "shí", "jì", "wèi", "dào", "zěn", "me", "yàng", ""], "vi": "Trái cây thì hợp. Bên đó đang bán nho, quảng cáo viết «vừa ngọt vừa to», nhưng không biết vị thực tế ra sao.", "en": "Fruit would be suitable. They're selling grapes over there, and the advertisement says \"sweet and big\", but I don't know what they actually taste like."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我们先买一丁点儿尝尝。要是味道不行，再看别的。", "p": ["nà", "wǒ", "men", "xiān", "mǎi", "yì", "dīng", "diǎn", "r", "cháng", "cháng", "", "yào", "shi", "wèi", "dào", "bù", "xíng", "", "zài", "kàn", "bié", "de", ""], "vi": "Vậy mình mua một chút nếm trước. Nếu vị không ổn thì xem thứ khác.", "en": "Then let's buy a little to taste first. If the flavour isn't right, we'll look at something else."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "也可以送一本小画册。她喜欢艺术，这算是一个优点：不贵，又记得住。", "p": ["yě", "kě", "yǐ", "sòng", "yì", "běn", "xiǎo", "huà", "cè", "", "tā", "xǐ", "huān", "yì", "shù", "", "zhè", "suàn", "shì", "yí", "gè", "yōu", "diǎn", "", "bú", "guì", "", "yòu", "jì", "de", "zhù", ""], "vi": "Cũng có thể tặng một tập tranh nhỏ. Cô thích nghệ thuật, đó là một ưu điểm: không đắt mà lại dễ nhớ.", "en": "We could also give her a little book of pictures. She likes art, and that's one advantage: it isn't expensive, and she'll remember it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就水果和画册都准备一点儿，让她选。", "p": ["nà", "jiù", "shuǐ", "guǒ", "hé", "huà", "cè", "dōu", "zhǔn", "bèi", "yì", "diǎn", "r", "", "ràng", "tā", "xuǎn", ""], "vi": "Vậy thì chuẩn bị cả trái cây lẫn tập tranh, để cô chọn.", "en": "Then let's get a little of both, the fruit and the picture book, and let her choose."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好。广告再好看，我们也先看东西本身。", "p": ["hǎo", "", "guǎng", "gào", "zài", "hǎo", "kàn", "", "wǒ", "men", "yě", "xiān", "kàn", "dōng", "xi", "běn", "shēn", ""], "vi": "Được. Quảng cáo đẹp đến mấy, mình cũng xem bản thân món đồ đã.", "en": "All right. However nice the advertisement is, we'll look at the thing itself first."}]}, {"n": 4, "zh": "短文：买衣服时我给自己的几条标准", "vi": "Đoạn văn: Vài tiêu chuẩn tôi đặt khi mua áo", "en": "Passage: A few standards I set myself when I buy clothes", "kw": ["标准", "考虑", "浪费", "年龄", "样子", "质量"], "lines": [{"s": "", "sp": [], "t": "以前我买衣服，只看样子新不新，偶尔还跟着流行走。穿过两次就不想再穿，等于把钱浪费了。后来我给自己定了几条标准：先考虑质量，再看颜色和大小是否适合我现在的年龄。样子可以简单，但一定要舒服、耐穿。这样买，衣服虽然少了，可每一件都能穿很久。", "p": ["yǐ", "qián", "wǒ", "mǎi", "yī", "fú", "", "zhǐ", "kàn", "yàng", "zi", "xīn", "bù", "xīn", "", "ǒu", "ěr", "hái", "gēn", "zhe", "liú", "xíng", "zǒu", "", "chuān", "guò", "liǎng", "cì", "jiù", "bù", "xiǎng", "zài", "chuān", "", "děng", "yú", "bǎ", "qián", "làng", "fèi", "le", "", "hòu", "lái", "wǒ", "gěi", "zì", "jǐ", "dìng", "le", "jǐ", "tiáo", "biāo", "zhǔn", "", "xiān", "kǎo", "lǜ", "zhì", "liàng", "", "zài", "kàn", "yán", "sè", "hé", "dà", "xiǎo", "shì", "fǒu", "shì", "hé", "wǒ", "xiàn", "zài", "de", "nián", "líng", "", "yàng", "zi", "kě", "yǐ", "jiǎn", "dān", "", "dàn", "yí", "dìng", "yào", "shū", "fú", "", "nài", "chuān", "", "zhè", "yàng", "mǎi", "", "yī", "fú", "suī", "rán", "shǎo", "le", "", "kě", "měi", "yí", "jiàn", "dōu", "néng", "chuān", "hěn", "jiǔ", ""], "vi": "Trước kia tôi mua áo chỉ nhìn kiểu mới hay không, đôi lúc còn theo mốt. Mặc hai lần đã không muốn mặc nữa, chẳng khác nào lãng phí tiền. Sau tôi đặt cho mình vài tiêu chuẩn: trước hãy xem xét chất lượng, rồi mới nhìn màu và kích cỡ có hợp với tuổi hiện tại không. Kiểu có thể đơn giản, nhưng phải thoải mái, bền. Mua như vậy, áo tuy ít hơn, nhưng mỗi món mặc được rất lâu.", "en": "I used to buy clothes only by whether the look was new, and sometimes I even followed the fashion. After wearing something twice I wouldn't want it again, which really meant I was wasting money. Later I set myself a few standards: consider the quality first, and then see whether the colour and size suit my age now. The style can be simple, but it must be comfortable and long-lasting. Buying this way, I have fewer clothes, but I can wear each piece for a long time."}]}, {"n": 5, "zh": "短文：网上购物也要停一停", "vi": "Đoạn văn: Mua hàng online cũng cần dừng lại một chút", "en": "Passage: Even when shopping online, it helps to pause", "kw": ["购物", "任何", "受到", "尤其", "寄", "家具"], "lines": [{"s": "", "sp": [], "t": "现在网上购物很方便，图片好看，手指一点，过两天东西就寄到家。可任何便利的背后，都可能让人买多。我曾经受到几张漂亮图片的影响，尤其是家具，看着眼红就下了单，收到后才发现房间根本放不下。后来我给自己定了个习惯：想买的东西先放一天，再决定要不要点。购物是为了用，不是为了点得痛快。", "p": ["xiàn", "zài", "wǎng", "shàng", "gòu", "wù", "hěn", "fāng", "biàn", "", "tú", "piàn", "hǎo", "kàn", "", "shǒu", "zhǐ", "yì", "diǎn", "", "guò", "liǎng", "tiān", "dōng", "xi", "jiù", "jì", "dào", "jiā", "", "kě", "rèn", "hé", "biàn", "lì", "de", "bèi", "hòu", "", "dōu", "kě", "néng", "ràng", "rén", "mǎi", "duō", "", "wǒ", "céng", "jīng", "shòu", "dào", "jǐ", "zhāng", "piào", "liàng", "tú", "piàn", "de", "yǐng", "xiǎng", "", "yóu", "qí", "shì", "jiā", "jù", "", "kàn", "zhe", "yǎn", "hóng", "jiù", "xià", "le", "dān", "", "shōu", "dào", "hòu", "cái", "fā", "xiàn", "fáng", "jiān", "gēn", "běn", "fàng", "bú", "xià", "", "hòu", "lái", "wǒ", "gěi", "zì", "jǐ", "dìng", "le", "gè", "xí", "guàn", "", "xiǎng", "mǎi", "de", "dōng", "xi", "xiān", "fàng", "yì", "tiān", "", "zài", "jué", "dìng", "yào", "bú", "yào", "diǎn", "", "gòu", "wù", "shì", "wèi", "le", "yòng", "", "bú", "shì", "wèi", "le", "diǎn", "de", "tòng", "kuai", ""], "vi": "Giờ mua sắm trên mạng rất tiện, ảnh đẹp, một cái chạm tay, vài hôm sau đồ đã được gửi tới nhà. Nhưng đằng sau bất kỳ sự tiện nào cũng có thể khiến người ta mua nhiều. Tôi từng chịu ảnh hưởng của vài tấm ảnh đẹp, nhất là đồ nội thất, nhìn ham là đặt, nhận xong mới thấy phòng chẳng để vừa. Sau tôi đặt cho mình một thói quen: món muốn mua để đó một ngày, rồi mới quyết có bấm không. Mua sắm là để dùng, không phải để bấm cho đã.", "en": "Shopping online is very convenient now: the pictures look nice, you tap once, and in a couple of days the things are sent to your home. But behind any convenience there is a chance you'll buy too much. I was once influenced by a few attractive pictures, especially of furniture; I ordered while my eyes were still hungry for it, and only when it arrived did I find it wouldn't fit in the room at all. Later I gave myself a habit: I leave anything I want to buy for a day, and only then decide whether to click. You shop in order to use things, not in order to enjoy clicking."}]}]}, {"l": 6, "texts": [{"n": 1, "zh": "阿玲去健身房", "vi": "A Linh đi phòng tập", "en": "A Linh goes to the gym", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你竟然每天早上都去健身房？真厉害！", "p": ["nǐ", "jìng", "rán", "měi", "tiān", "zǎo", "shàng", "dōu", "qù", "jiàn", "shēn", "fáng", "", "zhēn", "lì", "hài", ""], "vi": "Cậu sáng nào cũng đi phòng tập á? Giỏi thật!", "en": "You actually go to the gym every morning? Impressive!"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "健身房在举办活动，这个月免费，当然值得去。", "p": ["jiàn", "shēn", "fáng", "zài", "jǔ", "bàn", "huó", "dòng", "", "zhè", "ge", "yuè", "miǎn", "fèi", "", "dāng", "rán", "zhí", "de", "qù", ""], "vi": "Phòng tập đang tổ chức chương trình, tháng này miễn phí, đương nhiên đáng đi rồi.", "en": "The gym is running a promotion — it's free this month, so of course it's worth going."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "运动有什么好处？", "p": ["yùn", "dòng", "yǒu", "shén", "me", "hǎo", "chù", ""], "vi": "Tập thể dục có lợi ích gì?", "en": "What are the benefits of exercise?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好处很多，例如睡得好、皮肤好，心情也轻松。", "p": ["hǎo", "chù", "hěn", "duō", "", "lì", "rú", "shuì", "de", "hǎo", "", "pí", "fū", "hǎo", "", "xīn", "qíng", "yě", "qīng", "sōng", ""], "vi": "Nhiều lắm, ví dụ ngủ ngon, da đẹp, tâm trạng cũng thoải mái.", "en": "Lots — for example, you sleep well, your skin looks good, and you feel relaxed."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我也想试试。不过我怕坚持不下来。", "p": ["nà", "wǒ", "yě", "xiǎng", "shì", "shì", "", "bú", "guò", "wǒ", "pà", "jiān", "chí", "bú", "xià", "lái", ""], "vi": "Vậy mình cũng muốn thử. Có điều mình sợ không kiên trì được.", "en": "Then I want to try too. But I'm afraid I won't stick with it."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "在我的支持下，你一定可以！明天早上我叫你。", "p": ["zài", "wǒ", "de", "zhī", "chí", "xià", "", "nǐ", "yí", "dìng", "kě", "yǐ", "", "míng", "tiān", "zǎo", "shàng", "wǒ", "jiào", "nǐ", ""], "vi": "Có mình ủng hộ, cậu nhất định làm được! Sáng mai mình gọi cậu dậy.", "en": "With my support you'll definitely manage! I'll wake you tomorrow morning."}]}, {"n": 2, "zh": "短文：生活中不缺少美", "vi": "Đoạn văn: Cuộc sống không thiếu cái đẹp", "en": "Passage: Life is full of beauty", "kw": [], "lines": [{"s": "", "sp": [], "t": "生活中不缺少美，只是缺少发现美的眼睛。早上一杯新鲜的果汁，路边一朵小花，朋友一句关心的话，都能让人感到幸福。阿玲有一个小本子，里面记满了每天让她开心的事情，其中有的很小，例如售货员的一个微笑。她说，写下来以后，快乐好像增加了好几倍。", "p": ["shēng", "huó", "zhōng", "bù", "quē", "shǎo", "měi", "", "zhǐ", "shì", "quē", "shǎo", "fā", "xiàn", "měi", "de", "yǎn", "jīng", "", "zǎo", "shàng", "yì", "bēi", "xīn", "xiān", "de", "guǒ", "zhī", "", "lù", "biān", "yì", "duǒ", "xiǎo", "huā", "", "péng", "you", "yí", "jù", "guān", "xīn", "de", "huà", "", "dōu", "néng", "ràng", "rén", "gǎn", "dào", "xìng", "fú", "", "ā", "líng", "yǒu", "yí", "gè", "xiǎo", "běn", "zi", "", "lǐ", "miàn", "jì", "mǎn", "le", "měi", "tiān", "ràng", "tā", "kāi", "xīn", "de", "shì", "qíng", "", "qí", "zhōng", "yǒu", "de", "hěn", "xiǎo", "", "lì", "rú", "shòu", "huò", "yuán", "de", "yí", "gè", "wēi", "xiào", "", "tā", "shuō", "", "xiě", "xià", "lái", "yǐ", "hòu", "", "kuài", "lè", "hǎo", "xiàng", "zēng", "jiā", "le", "hǎo", "jǐ", "bèi", ""], "vi": "Cuộc sống không thiếu cái đẹp, chỉ thiếu đôi mắt biết phát hiện cái đẹp. Một ly nước ép tươi buổi sáng, một bông hoa nhỏ bên đường, một câu hỏi han của bạn bè đều có thể khiến người ta cảm thấy hạnh phúc. A Linh có một cuốn sổ nhỏ, ghi đầy những điều khiến cô vui mỗi ngày, trong đó có những điều rất nhỏ, ví dụ nụ cười của cô bán hàng. Cô nói, sau khi viết ra, niềm vui dường như tăng lên mấy lần.", "en": "Life isn't short of beauty, only of eyes that notice it. A glass of fresh juice in the morning, a little flower by the road, a caring word from a friend — all can make us feel happy. A Linh has a small notebook full of things that made her happy each day; some are very small, like a shop assistant's smile. She says that after writing them down, her happiness seems to multiply several times."}]}]}, {"l": 7, "texts": [{"n": 1, "zh": "阿玲感冒了", "vi": "A Linh bị cảm", "en": "A Linh has a cold", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你怎么一直咳嗽？是不是感冒了？", "p": ["nǐ", "zěn", "me", "yì", "zhí", "ké", "sòu", "", "shì", "bú", "shì", "gǎn", "mào", "le", ""], "vi": "Sao cậu ho mãi thế? Có phải bị cảm rồi không?", "en": "Why do you keep coughing? Have you caught a cold?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "估计是昨天晚上开着窗户睡觉，着凉了。", "p": ["gū", "jì", "shì", "zuó", "tiān", "wǎn", "shàng", "kāi", "zhe", "chuāng", "hù", "shuì", "jiào", "", "zháo", "liáng", "le", ""], "vi": "Chắc là tối qua mở cửa sổ ngủ nên bị nhiễm lạnh.", "en": "Probably because I slept with the window open last night and caught a chill."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "要是很严重，就去看大夫吧。", "p": ["yào", "shi", "hěn", "yán", "zhòng", "", "jiù", "qù", "kàn", "dà", "fū", "ba", ""], "vi": "Nếu nặng thì đi khám bác sĩ đi.", "en": "If it's serious, go and see a doctor."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "不严重。我既不发烧，也不头疼，多喝点儿热水就好了。", "p": ["bù", "yán", "zhòng", "", "wǒ", "jì", "bù", "fā", "shāo", "", "yě", "bù", "tóu", "téng", "", "duō", "hē", "diǎn", "r", "rè", "shuǐ", "jiù", "hǎo", "le", ""], "vi": "Không nặng đâu. Mình vừa không sốt vừa không đau đầu, uống nhiều nước ấm là khỏi.", "en": "It's not serious. I've no fever and no headache; drinking more hot water will sort it out."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "最近气候变化大，你别为了减肥不吃饭。", "p": ["zuì", "jìn", "qì", "hòu", "biàn", "huà", "dà", "", "nǐ", "bié", "wèi", "le", "jiǎn", "féi", "bù", "chī", "fàn", ""], "vi": "Dạo này thời tiết thay đổi nhiều, cậu đừng vì giảm cân mà nhịn ăn nhé.", "en": "The weather's been changeable lately, so don't skip meals to lose weight."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "知道了。等我好了，我们每天晚上一起去散散步。", "p": ["zhī", "dào", "le", "", "děng", "wǒ", "hǎo", "le", "", "wǒ", "men", "měi", "tiān", "wǎn", "shàng", "yì", "qǐ", "qù", "sàn", "sàn", "bù", ""], "vi": "Mình biết rồi. Đợi mình khỏi, tối nào bọn mình cũng cùng đi dạo nhé.", "en": "Got it. When I'm better, let's go for a walk together every evening."}]}, {"n": 2, "zh": "短文：最好的医生是自己", "vi": "Đoạn văn: Bác sĩ giỏi nhất là chính mình", "en": "Passage: The best doctor is yourself", "kw": [], "lines": [{"s": "", "sp": [], "t": "有一位教授说过，最好的医生是自己。研究说明，很多病和我们的生活习惯有关系，例如抽烟、睡得太晚、吃得太多等。要是每天坚持运动，多呼吸新鲜空气，少给自己找烦恼，身体自然就会健康。不要等到生病了才后悔，那时候可能就来不及了。", "p": ["yǒu", "yí", "wèi", "jiào", "shòu", "shuō", "guò", "", "zuì", "hǎo", "de", "yī", "shēng", "shì", "zì", "jǐ", "", "yán", "jiū", "shuō", "míng", "", "hěn", "duō", "bìng", "hé", "wǒ", "men", "de", "shēng", "huó", "xí", "guàn", "yǒu", "guān", "xì", "", "lì", "rú", "chōu", "yān", "", "shuì", "de", "tài", "wǎn", "", "chī", "de", "tài", "duō", "děng", "", "yào", "shi", "měi", "tiān", "jiān", "chí", "yùn", "dòng", "", "duō", "hū", "xī", "xīn", "xiān", "kōng", "qì", "", "shǎo", "gěi", "zì", "jǐ", "zhǎo", "fán", "nǎo", "", "shēn", "tǐ", "zì", "rán", "jiù", "huì", "jiàn", "kāng", "", "bú", "yào", "děng", "dào", "shēng", "bìng", "le", "cái", "hòu", "huǐ", "", "nà", "shí", "hòu", "kě", "néng", "jiù", "lái", "bù", "jí", "le", ""], "vi": "Có một vị giáo sư từng nói, bác sĩ giỏi nhất là chính mình. Nghiên cứu cho thấy rất nhiều bệnh có liên quan đến thói quen sinh hoạt của chúng ta, ví dụ hút thuốc, ngủ quá muộn, ăn quá nhiều… Nếu mỗi ngày kiên trì vận động, hít thở nhiều không khí trong lành, bớt tự chuốc phiền não, cơ thể tự nhiên sẽ khỏe mạnh. Đừng đợi đến khi bị bệnh mới hối hận, lúc đó có thể đã không kịp nữa rồi.", "en": "A professor once said that the best doctor is yourself. Research shows that many illnesses are linked to our habits — smoking, going to bed too late, overeating and so on. If you exercise every day, breathe plenty of fresh air and don't go looking for worries, your body will naturally stay healthy. Don't wait until you're ill to regret it; by then it may be too late."}]}]}, {"l": 8, "texts": [{"n": 1, "zh": "阿玲心情不好", "vi": "A Linh buồn", "en": "A Linh is feeling down", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你今天怎么不太愉快？发生什么事了？", "p": ["nǐ", "jīn", "tiān", "zěn", "me", "bú", "tài", "yú", "kuài", "", "fā", "shēng", "shén", "me", "shì", "le", ""], "vi": "Hôm nay sao cậu không vui lắm? Có chuyện gì vậy?", "en": "Why aren't you very cheerful today? What happened?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "最近压力太大了，考试没考好，我有点儿伤心。", "p": ["zuì", "jìn", "yā", "lì", "tài", "dà", "le", "", "kǎo", "shì", "méi", "kǎo", "hǎo", "", "wǒ", "yǒu", "diǎn", "r", "shāng", "xīn", ""], "vi": "Dạo này áp lực lớn quá, thi không tốt nên mình hơi buồn.", "en": "I've been under so much pressure lately, and I didn't do well in my exam. I'm a bit upset."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别难过。只要你努力了，下次一定会更好。", "p": ["bié", "nán", "guò", "", "zhǐ", "yào", "nǐ", "nǔ", "lì", "le", "", "xià", "cì", "yí", "dìng", "huì", "gèng", "hǎo", ""], "vi": "Đừng buồn. Chỉ cần cậu đã cố gắng, lần sau nhất định sẽ tốt hơn.", "en": "Don't be sad. As long as you've tried hard, next time will definitely be better."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "可不是嘛，伤心也没用。我想出去放松一下。", "p": ["kě", "bú", "shì", "ma", "", "shāng", "xīn", "yě", "méi", "yòng", "", "wǒ", "xiǎng", "chū", "qù", "fàng", "sōng", "yí", "xià", ""], "vi": "Đúng thế, buồn cũng chẳng ích gì. Mình muốn ra ngoài thư giãn một chút.", "en": "You're right, being upset won't help. I want to go out and relax."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "今天阳光这么好，我们去公园看看景色吧，再买块巧克力！", "p": ["jīn", "tiān", "yáng", "guāng", "zhè", "me", "hǎo", "", "wǒ", "men", "qù", "gōng", "yuán", "kàn", "kàn", "jǐng", "sè", "ba", "", "zài", "mǎi", "kuài", "qiǎo", "kè", "lì", ""], "vi": "Hôm nay nắng đẹp thế này, mình ra công viên ngắm cảnh đi, mua thêm thanh sô-cô-la nữa!", "en": "It's so sunny today — let's go to the park to enjoy the scenery, and buy some chocolate!"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好啊！和你在一起，我的心情马上变好了。", "p": ["hǎo", "a", "", "hé", "nǐ", "zài", "yì", "qǐ", "", "wǒ", "de", "xīn", "qíng", "mǎ", "shàng", "biàn", "hǎo", "le", ""], "vi": "Được đó! Ở bên cậu, tâm trạng mình tốt lên ngay.", "en": "Sure! Being with you cheers me up straight away."}]}, {"n": 2, "zh": "短文：态度决定心情", "vi": "Đoạn văn: Thái độ quyết định tâm trạng", "en": "Passage: Attitude decides your mood", "kw": [], "lines": [{"s": "", "sp": [], "t": "同一件事，不同的人往往有不同的态度。堵车的时候，有人很着急，有人却听听音乐，看看窗外的景色。科学证明，积极的态度能使人减少压力，心情也会更愉快。生命中总会有让人伤心的事情，因此我们要学会耐心地等待，相信阳光总在风雨后。", "p": ["tóng", "yí", "jiàn", "shì", "", "bù", "tóng", "de", "rén", "wǎng", "wǎng", "yǒu", "bù", "tóng", "de", "tài", "dù", "", "dǔ", "chē", "de", "shí", "hòu", "", "yǒu", "rén", "hěn", "zháo", "jí", "", "yǒu", "rén", "què", "tīng", "tīng", "yīn", "yuè", "", "kàn", "kàn", "chuāng", "wài", "de", "jǐng", "sè", "", "kē", "xué", "zhèng", "míng", "", "jī", "jí", "de", "tài", "dù", "néng", "shǐ", "rén", "jiǎn", "shǎo", "yā", "lì", "", "xīn", "qíng", "yě", "huì", "gèng", "yú", "kuài", "", "shēng", "mìng", "zhòng", "zǒng", "huì", "yǒu", "ràng", "rén", "shāng", "xīn", "de", "shì", "qíng", "", "yīn", "cǐ", "wǒ", "men", "yào", "xué", "huì", "nài", "xīn", "dì", "děng", "dài", "", "xiāng", "xìn", "yáng", "guāng", "zǒng", "zài", "fēng", "yǔ", "hòu", ""], "vi": "Cùng một việc, những người khác nhau thường có thái độ khác nhau. Khi tắc đường, có người rất sốt ruột, có người lại nghe nhạc, ngắm cảnh ngoài cửa sổ. Khoa học chứng minh, thái độ tích cực có thể giúp con người giảm áp lực, tâm trạng cũng vui vẻ hơn. Trong cuộc đời luôn có những chuyện khiến người ta buồn, vì vậy chúng ta phải học cách kiên nhẫn chờ đợi, tin rằng sau mưa trời lại sáng.", "en": "Different people often take different attitudes to the same thing. In a traffic jam, some get anxious while others listen to music and enjoy the view outside. Science has shown that a positive attitude reduces stress and makes us happier. Life will always bring sad moments, so we should learn to wait patiently and believe the sun always comes out after the storm."}]}]}, {"l": 9, "texts": [{"n": 1, "zh": "阿玲学打网球", "vi": "A Linh học đánh tennis", "en": "A Linh learns tennis", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你学网球多久了？", "p": ["nǐ", "xué", "wǎng", "qiú", "duō", "jiǔ", "le", ""], "vi": "Cậu học tennis bao lâu rồi?", "en": "How long have you been learning tennis?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "才一个月。开始的时候总是输，我差点儿就放弃了。", "p": ["cái", "yí", "gè", "yuè", "", "kāi", "shǐ", "de", "shí", "hòu", "zǒng", "shì", "shū", "", "wǒ", "chà", "diǎn", "r", "jiù", "fàng", "qì", "le", ""], "vi": "Mới một tháng. Lúc đầu toàn thua, mình suýt nữa bỏ cuộc.", "en": "Only a month. At first I always lost, and I nearly gave up."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "难道你现在能赢了？", "p": ["nán", "dào", "nǐ", "xiàn", "zài", "néng", "yíng", "le", ""], "vi": "Chẳng lẽ bây giờ cậu thắng được rồi à?", "en": "Don't tell me you can win now?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "通过每天练习，我上个星期终于赢了一次！", "p": ["tōng", "guò", "měi", "tiān", "liàn", "xí", "", "wǒ", "shàng", "gè", "xīng", "qī", "zhōng", "yú", "yíng", "le", "yí", "cì", ""], "vi": "Nhờ luyện tập mỗi ngày, tuần trước cuối cùng mình đã thắng một lần!", "en": "Through practising every day, I finally won once last week!"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "太棒了！不过每天练习，不累吗？", "p": ["tài", "bàng", "le", "", "bú", "guò", "měi", "tiān", "liàn", "xí", "", "bú", "lèi", "ma", ""], "vi": "Tuyệt quá! Có điều ngày nào cũng tập, không mệt sao?", "en": "Fantastic! But isn't practising every day tiring?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "累是累，可是出一身汗以后特别轻松。坚持下去，结果一定不错。", "p": ["lèi", "shì", "lèi", "", "kě", "shì", "chū", "yì", "shēn", "hàn", "yǐ", "hòu", "tè", "bié", "qīng", "sōng", "", "jiān", "chí", "xià", "qù", "", "jié", "guǒ", "yí", "dìng", "bú", "cuò", ""], "vi": "Mệt thì có mệt, nhưng ra mồ hôi xong thấy rất nhẹ nhõm. Kiên trì tiếp, kết quả chắc chắn sẽ tốt.", "en": "It is tiring, but after a good sweat I feel so relaxed. If I keep going, the result is bound to be good."}]}, {"n": 2, "zh": "短文：失败是成功之母", "vi": "Đoạn văn: Thất bại là mẹ thành công", "en": "Passage: Failure is the mother of success", "kw": [], "lines": [{"s": "", "sp": [], "t": "每个人都会经历失败。有一位作家写第一篇小说时，被拒绝了二十多次。当时很多人劝他换个工作，可是他没有放弃，而是总结每次失败的原因。结果，他的书后来卖了许多本。失败并不可怕，可怕的是不敢再试。只要方向正确，至少我们离理想又近了一步。", "p": ["měi", "gè", "rén", "dōu", "huì", "jīng", "lì", "shī", "bài", "", "yǒu", "yí", "wèi", "zuò", "jiā", "xiě", "dì", "yī", "piān", "xiǎo", "shuō", "shí", "", "bèi", "jù", "jué", "le", "èr", "shí", "duō", "cì", "", "dāng", "shí", "hěn", "duō", "rén", "quàn", "tā", "huàn", "gè", "gōng", "zuò", "", "kě", "shì", "tā", "méi", "yǒu", "fàng", "qì", "", "ér", "shì", "zǒng", "jié", "měi", "cì", "shī", "bài", "de", "yuán", "yīn", "", "jié", "guǒ", "", "tā", "de", "shū", "hòu", "lái", "mài", "le", "xǔ", "duō", "běn", "", "shī", "bài", "bìng", "bù", "kě", "pà", "", "kě", "pà", "de", "shì", "bù", "gǎn", "zài", "shì", "", "zhǐ", "yào", "fāng", "xiàng", "zhèng", "què", "", "zhì", "shǎo", "wǒ", "men", "lí", "lǐ", "xiǎng", "yòu", "jìn", "le", "yí", "bù", ""], "vi": "Ai cũng sẽ trải qua thất bại. Có một nhà văn khi viết cuốn tiểu thuyết đầu tiên đã bị từ chối hơn hai mươi lần. Lúc đó nhiều người khuyên ông đổi nghề, nhưng ông không bỏ cuộc mà tổng kết nguyên nhân của mỗi lần thất bại. Kết quả, sau này sách của ông bán được rất nhiều. Thất bại không đáng sợ, đáng sợ là không dám thử lại. Chỉ cần đi đúng hướng, ít nhất chúng ta lại tiến gần ước mơ thêm một bước.", "en": "Everyone experiences failure. One writer was rejected more than twenty times with his first novel. At the time many people urged him to change jobs, but he didn't give up; instead he summed up the reasons for each failure. In the end his books sold many copies. Failure isn't frightening; what's frightening is not daring to try again. As long as the direction is right, at least we're one step closer to our dream."}]}]}, {"l": 10, "texts": [{"n": 1, "zh": "阿玲考虑将来", "vi": "A Linh nghĩ về tương lai", "en": "A Linh thinks about the future", "kw": [], "lines": [{"s": "陈老师", "sp": ["chén", "lǎo", "shī"], "t": "阿玲，毕业以后你有什么打算？", "p": ["ā", "líng", "", "bì", "yè", "yǐ", "hòu", "nǐ", "yǒu", "shén", "me", "dǎ", "suàn", ""], "vi": "A Linh, tốt nghiệp xong em có dự định gì?", "en": "A Linh, what are your plans after graduating?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想读硕士，不过也想早点儿工作，现在还没有答案。", "p": ["wǒ", "xiǎng", "dú", "shuò", "shì", "", "bú", "guò", "yě", "xiǎng", "zǎo", "diǎn", "r", "gōng", "zuò", "", "xiàn", "zài", "hái", "méi", "yǒu", "dá", "àn", ""], "vi": "Em muốn học thạc sĩ, nhưng cũng muốn đi làm sớm, bây giờ vẫn chưa có câu trả lời.", "en": "I'd like to do a master's, but I also want to start working soon. I haven't decided yet."}, {"s": "陈老师", "sp": ["chén", "lǎo", "shī"], "t": "在我看来，你的中文这么优秀，做翻译是个好方向。", "p": ["zài", "wǒ", "kàn", "lái", "", "nǐ", "de", "zhōng", "wén", "zhè", "me", "yōu", "xiù", "", "zuò", "fān", "yì", "shì", "gè", "hǎo", "fāng", "xiàng", ""], "vi": "Theo cô thấy, tiếng Trung của em giỏi như vậy, làm phiên dịch là một hướng tốt.", "en": "In my view, your Chinese is so good that translation would be a great direction."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "由于越南和中国的经济发展很快，翻译确实很受欢迎。", "p": ["yóu", "yú", "yuè", "nán", "hé", "zhōng", "guó", "de", "jīng", "jì", "fā", "zhǎn", "hěn", "kuài", "", "fān", "yì", "què", "shí", "hěn", "shòu", "huān", "yíng", ""], "vi": "Do kinh tế Việt Nam và Trung Quốc phát triển nhanh, phiên dịch đúng là rất được ưa chuộng.", "en": "Because the economies of Vietnam and China are growing fast, translators really are in demand."}, {"s": "陈老师", "sp": ["chén", "lǎo", "shī"], "t": "对。比如旅游、贸易，都需要会两种语言的人。", "p": ["duì", "", "bǐ", "rú", "lǚ", "yóu", "", "mào", "yì", "", "dōu", "xū", "yào", "huì", "liǎng", "zhǒng", "yǔ", "yán", "de", "rén", ""], "vi": "Đúng vậy. Ví dụ du lịch, thương mại đều cần người biết hai ngôn ngữ.", "en": "That's right. Tourism and trade, for example, both need people who speak two languages."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "谢谢老师的建议，我会认真考虑的。", "p": ["xiè", "xiè", "lǎo", "shī", "de", "jiàn", "yì", "", "wǒ", "huì", "rèn", "zhēn", "kǎo", "lǜ", "de", ""], "vi": "Cảm ơn lời khuyên của cô, em sẽ suy nghĩ nghiêm túc.", "en": "Thank you for your advice. I'll think it over carefully."}]}, {"n": 2, "zh": "短文：幸福是什么", "vi": "Đoạn văn: Hạnh phúc là gì", "en": "Passage: What is happiness", "kw": [], "lines": [{"s": "", "sp": [], "t": "什么是幸福？不同的人有不同的答案。有人觉得富就是幸福，有人觉得有个好职业就是幸福。阿玲的母亲说，幸福就是礼拜天全家人坐在一起吃饭、聊天。由于每个人的条件不一样，幸福的样子也不一样。不过，关键是要珍惜现在拥有的东西，这样我们才能永远快乐。", "p": ["shén", "me", "shì", "xìng", "fú", "", "bù", "tóng", "de", "rén", "yǒu", "bù", "tóng", "de", "dá", "àn", "", "yǒu", "rén", "jué", "de", "fù", "jiù", "shì", "xìng", "fú", "", "yǒu", "rén", "jué", "de", "yǒu", "gè", "hǎo", "zhí", "yè", "jiù", "shì", "xìng", "fú", "", "ā", "líng", "de", "mǔ", "qīn", "shuō", "", "xìng", "fú", "jiù", "shì", "lǐ", "bài", "tiān", "quán", "jiā", "rén", "zuò", "zài", "yì", "qǐ", "chī", "fàn", "", "liáo", "tiān", "", "yóu", "yú", "měi", "gè", "rén", "de", "tiáo", "jiàn", "bù", "yí", "yàng", "", "xìng", "fú", "de", "yàng", "zi", "yě", "bù", "yí", "yàng", "", "bú", "guò", "", "guān", "jiàn", "shì", "yào", "zhēn", "xī", "xiàn", "zài", "yōng", "yǒu", "de", "dōng", "xi", "", "zhè", "yàng", "wǒ", "men", "cái", "néng", "yǒng", "yuǎn", "kuài", "lè", ""], "vi": "Hạnh phúc là gì? Mỗi người có một câu trả lời khác nhau. Có người cho rằng giàu có là hạnh phúc, có người cho rằng có nghề nghiệp tốt là hạnh phúc. Mẹ của A Linh nói, hạnh phúc là ngày chủ nhật cả nhà ngồi cùng nhau ăn cơm, trò chuyện. Do điều kiện mỗi người không giống nhau, hình dáng của hạnh phúc cũng khác nhau. Tuy nhiên, điều then chốt là phải trân trọng những gì đang có, như vậy chúng ta mới có thể vui vẻ mãi mãi.", "en": "What is happiness? Different people give different answers. Some think being rich is happiness; others think it's having a good career. A Linh's mother says happiness is the whole family sitting together on Sunday, eating and chatting. Because everyone's circumstances differ, happiness looks different too. But the key is to cherish what we have now — only then can we be happy for ever."}]}]}, {"l": 11, "texts": [{"n": 1, "zh": "阿玲学习阅读", "vi": "A Linh luyện đọc hiểu", "en": "A Linh practises reading", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "这篇文章的内容太复杂了，连题目我都看不懂。", "p": ["zhè", "piān", "wén", "zhāng", "de", "nèi", "róng", "tài", "fù", "zá", "le", "", "lián", "tí", "mù", "wǒ", "dōu", "kàn", "bù", "dǒng", ""], "vi": "Nội dung bài văn này phức tạp quá, đến cả đề bài mình cũng không hiểu.", "en": "This article is so complicated that I can't even understand the title."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别着急。你可以先猜一猜词语的意思，同时看看上下文。", "p": ["bié", "zháo", "jí", "", "nǐ", "kě", "yǐ", "xiān", "cāi", "yì", "cāi", "cí", "yǔ", "de", "yì", "si", "", "tóng", "shí", "kàn", "kàn", "shàng", "xià", "wén", ""], "vi": "Đừng vội. Cậu có thể đoán nghĩa của từ trước, đồng thời xem ngữ cảnh trước sau.", "en": "Don't worry. You can guess the meaning of the words first and look at the context at the same time."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "可是考试的时候来得及吗？", "p": ["kě", "shì", "kǎo", "shì", "de", "shí", "hòu", "lái", "de", "jí", "ma", ""], "vi": "Nhưng lúc thi có kịp không?", "en": "But will there be enough time in the exam?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "所以平时要养成读书的习惯，否则考试时就会很紧张。", "p": ["suǒ", "yǐ", "píng", "shí", "yào", "yǎng", "chéng", "dú", "shū", "de", "xí", "guàn", "", "fǒu", "zé", "kǎo", "shì", "shí", "jiù", "huì", "hěn", "jǐn", "zhāng", ""], "vi": "Vì vậy bình thường phải tạo thói quen đọc sách, nếu không lúc thi sẽ rất căng thẳng.", "en": "That's why you need to make reading a habit, otherwise you'll be very nervous in the exam."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "无论多忙，我每天都读五页中文杂志，怎么样？", "p": ["wú", "lùn", "duō", "máng", "", "wǒ", "měi", "tiān", "dōu", "dú", "wǔ", "yè", "zhōng", "wén", "zá", "zhì", "", "zěn", "me", "yàng", ""], "vi": "Dù bận đến đâu, mỗi ngày mình đọc năm trang tạp chí tiếng Trung, được không?", "en": "No matter how busy I am, I'll read five pages of a Chinese magazine every day. How's that?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好主意！坚持下去，你的阅读一定会越来越流利。", "p": ["hǎo", "zhǔ", "yi", "", "jiān", "chí", "xià", "qù", "", "nǐ", "de", "yuè", "dú", "yí", "dìng", "huì", "yuè", "lái", "yuè", "liú", "lì", ""], "vi": "Ý hay! Kiên trì, khả năng đọc của cậu nhất định sẽ ngày càng trôi chảy.", "en": "Good idea! Keep it up and your reading will get more and more fluent."}]}, {"n": 2, "zh": "短文：读书的乐趣", "vi": "Đoạn văn: Niềm vui đọc sách", "en": "Passage: The joy of reading", "kw": [], "lines": [{"s": "", "sp": [], "t": "读书可以增加知识，同时也能让我们放松心情。很多著名的人都有每天阅读的习惯。然而，现在很多年轻人只看手机，很少读完一本书。其实读书不需要很多时间，每天读十几页就够了。在客厅放几本自己喜欢的书，有空儿的时候拿起来看看，慢慢地你就会发现读书的精彩。", "p": ["dú", "shū", "kě", "yǐ", "zēng", "jiā", "zhī", "shí", "", "tóng", "shí", "yě", "néng", "ràng", "wǒ", "men", "fàng", "sōng", "xīn", "qíng", "", "hěn", "duō", "zhù", "míng", "de", "rén", "dōu", "yǒu", "měi", "tiān", "yuè", "dú", "de", "xí", "guàn", "", "rán", "ér", "", "xiàn", "zài", "hěn", "duō", "nián", "qīng", "rén", "zhǐ", "kàn", "shǒu", "jī", "", "hěn", "shǎo", "dú", "wán", "yì", "běn", "shū", "", "qí", "shí", "dú", "shū", "bù", "xū", "yào", "hěn", "duō", "shí", "jiān", "", "měi", "tiān", "dú", "shí", "jǐ", "yè", "jiù", "gòu", "le", "", "zài", "kè", "tīng", "fàng", "jǐ", "běn", "zì", "jǐ", "xǐ", "huān", "de", "shū", "", "yǒu", "kòng", "r", "de", "shí", "hòu", "ná", "qǐ", "lái", "kàn", "kàn", "", "màn", "màn", "dì", "nǐ", "jiù", "huì", "fā", "xiàn", "dú", "shū", "de", "jīng", "cǎi", ""], "vi": "Đọc sách có thể tăng thêm kiến thức, đồng thời cũng giúp chúng ta thư giãn. Nhiều người nổi tiếng có thói quen đọc sách mỗi ngày. Tuy nhiên, bây giờ nhiều bạn trẻ chỉ xem điện thoại, rất ít khi đọc hết một cuốn sách. Thật ra đọc sách không cần nhiều thời gian, mỗi ngày đọc mười mấy trang là đủ. Đặt vài cuốn sách mình thích trong phòng khách, lúc rảnh cầm lên đọc, dần dần bạn sẽ phát hiện ra cái hay của việc đọc sách.", "en": "Reading increases our knowledge and also helps us relax. Many famous people read every day. Yet many young people today only look at their phones and rarely finish a book. In fact reading doesn't take much time — a dozen or so pages a day is enough. Keep a few books you like in the living room and pick one up when you're free; gradually you'll discover how wonderful reading is."}]}]}, {"l": 12, "texts": [{"n": 1, "zh": "阿玲学做越南菜", "vi": "A Linh dạy nấu món Việt", "en": "A Linh teaches Vietnamese cooking", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "阿玲，你能教我做越南春卷吗？", "p": ["ā", "líng", "", "nǐ", "néng", "jiāo", "wǒ", "zuò", "yuè", "nán", "chūn", "juǎn", "ma", ""], "vi": "A Linh, cậu dạy mình làm nem cuốn Việt Nam được không?", "en": "A Linh, can you teach me to make Vietnamese spring rolls?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "当然可以。先把菜洗干净，并且要仔细地切好。", "p": ["dāng", "rán", "kě", "yǐ", "", "xiān", "bǎ", "cài", "xǐ", "gān", "jìng", "", "bìng", "qiě", "yào", "zǐ", "xì", "dì", "qiè", "hǎo", ""], "vi": "Tất nhiên rồi. Trước tiên rửa sạch rau, và phải thái cẩn thận.", "en": "Of course. First wash the vegetables, and cut them carefully."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "要放多少盐？用这个勺子可以吗？", "p": ["yào", "fàng", "duō", "shǎo", "yán", "", "yòng", "zhè", "ge", "sháo", "zi", "kě", "yǐ", "ma", ""], "vi": "Phải cho bao nhiêu muối? Dùng cái thìa này được không?", "en": "How much salt should I add? Can I use this spoon?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "只放一点儿就行。对于越南菜来说，酱汁的作用最大。", "p": ["zhǐ", "fàng", "yì", "diǎn", "r", "jiù", "xíng", "", "duì", "yú", "yuè", "nán", "cài", "lái", "shuō", "", "jiàng", "zhī", "de", "zuò", "yòng", "zuì", "dà", ""], "vi": "Chỉ cho một chút là được. Đối với món Việt, nước chấm đóng vai trò lớn nhất.", "en": "Just a little. For Vietnamese food, the dipping sauce plays the biggest role."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "太可惜了，我把卷饼弄破了。", "p": ["tài", "kě", "xī", "le", "", "wǒ", "bǎ", "juǎn", "bǐng", "nòng", "pò", "le", ""], "vi": "Tiếc quá, mình làm rách bánh tráng rồi.", "en": "Oh no, I've torn the rice paper."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "没关系，再难也别放弃。你看，这次卷得很好！", "p": ["méi", "guān", "xì", "", "zài", "nán", "yě", "bié", "fàng", "qì", "", "nǐ", "kàn", "", "zhè", "cì", "juǎn", "de", "hěn", "hǎo", ""], "vi": "Không sao, khó mấy cũng đừng bỏ cuộc. Cậu xem, lần này cuốn đẹp lắm!", "en": "Never mind — however hard it is, don't give up. Look, this one's rolled perfectly!"}]}, {"n": 2, "zh": "短文：语言和误会", "vi": "Đoạn văn: Ngôn ngữ và hiểu lầm", "en": "Passage: Language and misunderstandings", "kw": [], "lines": [{"s": "", "sp": [], "t": "学习一门语言，不只是学习语法和词语，还要了解别人的文化。有一次，阿玲的中国朋友问她：“你吃了吗？”她以为朋友要请她吃饭，结果引起了误会。后来朋友解释说，这只是打招呼的一种方法。相反，越南人见面常常问“你去哪儿？”。也许每种语言都有这样有趣的地方，我们应该友好地互相学习。", "p": ["xué", "xí", "yì", "mén", "yǔ", "yán", "", "bù", "zhǐ", "shì", "xué", "xí", "yǔ", "fǎ", "hé", "cí", "yǔ", "", "hái", "yào", "liǎo", "jiě", "bié", "rén", "de", "wén", "huà", "", "yǒu", "yí", "cì", "", "ā", "líng", "de", "zhōng", "guó", "péng", "you", "wèn", "tā", "", "", "nǐ", "chī", "le", "ma", "", "", "tā", "yǐ", "wéi", "péng", "you", "yào", "qǐng", "tā", "chī", "fàn", "", "jié", "guǒ", "yǐn", "qǐ", "le", "wù", "huì", "", "hòu", "lái", "péng", "you", "jiě", "shì", "shuō", "", "zhè", "zhǐ", "shì", "dǎ", "zhāo", "hu", "de", "yì", "zhǒng", "fāng", "fǎ", "", "xiāng", "fǎn", "", "yuè", "nán", "rén", "jiàn", "miàn", "cháng", "cháng", "wèn", "", "nǐ", "qù", "nǎ", "r", "", "", "", "yě", "xǔ", "měi", "zhǒng", "yǔ", "yán", "dōu", "yǒu", "zhè", "yàng", "yǒu", "qù", "de", "dì", "fāng", "", "wǒ", "men", "yīng", "gāi", "yǒu", "hǎo", "dì", "hù", "xiāng", "xué", "xí", ""], "vi": "Học một ngôn ngữ không chỉ là học ngữ pháp và từ vựng, mà còn phải hiểu văn hóa của người khác. Có lần bạn Trung Quốc của A Linh hỏi cô: \"Cậu ăn chưa?\" Cô tưởng bạn muốn mời mình đi ăn, kết quả gây ra hiểu lầm. Sau đó bạn giải thích rằng đây chỉ là một cách chào hỏi. Ngược lại, người Việt gặp nhau thường hỏi \"Đi đâu đấy?\". Có lẽ mỗi ngôn ngữ đều có những điểm thú vị như vậy, chúng ta nên học hỏi lẫn nhau một cách thân thiện.", "en": "Learning a language means not just learning grammar and words but also understanding other cultures. Once a Chinese friend asked A Linh, \"Have you eaten?\" She thought her friend was inviting her for a meal, which caused a misunderstanding. Her friend later explained it's just a way of saying hello. In contrast, Vietnamese people often greet each other with \"Where are you going?\". Perhaps every language has interesting things like this, and we should learn from each other in a friendly way."}]}]}, {"l": 13, "texts": [{"n": 1, "zh": "阿玲第一次看京剧", "vi": "A Linh lần đầu xem Kinh kịch", "en": "A Linh sees Peking opera for the first time", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "昨天的京剧表演怎么样？", "p": ["zuó", "tiān", "de", "jīng", "jù", "biǎo", "yǎn", "zěn", "me", "yàng", ""], "vi": "Buổi biểu diễn Kinh kịch hôm qua thế nào?", "en": "How was the Peking opera performance yesterday?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "十分精彩！演员的衣服特别漂亮，观众大概有五百人。", "p": ["shí", "fēn", "jīng", "cǎi", "", "yǎn", "yuán", "de", "yī", "fú", "tè", "bié", "piào", "liàng", "", "guān", "zhòng", "dà", "gài", "yǒu", "wǔ", "bǎi", "rén", ""], "vi": "Rất đặc sắc! Trang phục của diễn viên đặc biệt đẹp, khán giả khoảng năm trăm người.", "en": "Wonderful! The actors' costumes were beautiful, and there were about five hundred people in the audience."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你听得懂吗？", "p": ["nǐ", "tīng", "de", "dǒng", "ma", ""], "vi": "Cậu nghe hiểu không?", "en": "Could you understand it?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "只听懂一部分，不过旁边有字幕，稍微看一下就明白了。", "p": ["zhǐ", "tīng", "dǒng", "yí", "bù", "fèn", "", "bú", "guò", "páng", "biān", "yǒu", "zì", "mù", "", "shāo", "wēi", "kàn", "yí", "xià", "jiù", "míng", "bái", "le", ""], "vi": "Chỉ hiểu được một phần, nhưng bên cạnh có phụ đề, nhìn qua một chút là hiểu.", "en": "Only part of it, but there were subtitles at the side, so a quick look was enough."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我偶尔也去看。随着年龄增加，我越来越喜欢京剧了。", "p": ["wǒ", "ǒu", "ěr", "yě", "qù", "kàn", "", "suí", "zhe", "nián", "líng", "zēng", "jiā", "", "wǒ", "yuè", "lái", "yuè", "xǐ", "huān", "jīng", "jù", "le", ""], "vi": "Thỉnh thoảng mình cũng đi xem. Càng lớn tuổi mình càng thích Kinh kịch.", "en": "I go occasionally too. As I get older, I like Peking opera more and more."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "下次演出我们一起去吧，由我来买票！", "p": ["xià", "cì", "yǎn", "chū", "wǒ", "men", "yì", "qǐ", "qù", "ba", "", "yóu", "wǒ", "lái", "mǎi", "piào", ""], "vi": "Lần biểu diễn sau mình cùng đi nhé, để mình mua vé!", "en": "Let's go together to the next show — I'll buy the tickets!"}]}, {"n": 2, "zh": "短文：互联网和生活", "vi": "Đoạn văn: Internet và cuộc sống", "en": "Passage: The internet and daily life", "kw": [], "lines": [{"s": "", "sp": [], "t": "随着互联网的发展，我们的生活发生了很大的变化。现在，在网上申请工作、和来自世界各地的人讨论问题都非常普遍。阿玲每天晚上都和越南的家人视频，好像他们就在身边一样。不过，互联网也有缺点，有的人一上网就是好几个小时。所以，我们应该正确地使用它，让它成为生活的好帮手。", "p": ["suí", "zhe", "hù", "lián", "wǎng", "de", "fā", "zhǎn", "", "wǒ", "men", "de", "shēng", "huó", "fā", "shēng", "le", "hěn", "dà", "de", "biàn", "huà", "", "xiàn", "zài", "", "zài", "wǎng", "shàng", "shēn", "qǐng", "gōng", "zuò", "", "hé", "lái", "zì", "shì", "jiè", "gè", "dì", "de", "rén", "tǎo", "lùn", "wèn", "tí", "dōu", "fēi", "cháng", "pǔ", "biàn", "", "ā", "líng", "měi", "tiān", "wǎn", "shàng", "dōu", "hé", "yuè", "nán", "de", "jiā", "rén", "shì", "pín", "", "hǎo", "xiàng", "tā", "men", "jiù", "zài", "shēn", "biān", "yí", "yàng", "", "bú", "guò", "", "hù", "lián", "wǎng", "yě", "yǒu", "quē", "diǎn", "", "yǒu", "de", "rén", "yí", "shàng", "wǎng", "jiù", "shì", "hǎo", "jǐ", "gè", "xiǎo", "shí", "", "suǒ", "yǐ", "", "wǒ", "men", "yīng", "gāi", "zhèng", "què", "dì", "shǐ", "yòng", "tā", "", "ràng", "tā", "chéng", "wéi", "shēng", "huó", "de", "hǎo", "bāng", "shǒu", ""], "vi": "Cùng với sự phát triển của Internet, cuộc sống của chúng ta đã thay đổi rất nhiều. Bây giờ, xin việc trên mạng hay thảo luận với những người đến từ khắp nơi trên thế giới đều rất phổ biến. Tối nào A Linh cũng gọi video với gia đình ở Việt Nam, cứ như họ đang ở ngay bên cạnh. Tuy nhiên, Internet cũng có nhược điểm, có người đã lên mạng là mấy tiếng liền. Vì vậy, chúng ta nên sử dụng nó đúng cách, để nó trở thành người trợ thủ tốt trong cuộc sống.", "en": "With the development of the internet, our lives have changed enormously. Applying for jobs online or discussing things with people from all over the world is now very common. Every evening A Linh video-calls her family in Vietnam, as if they were right beside her. But the internet has its downsides too — some people spend hours online at a time. So we should use it properly and make it a good helper in our lives."}]}]}, {"l": 14, "texts": [{"n": 1, "zh": "阿玲出差", "vi": "A Linh đi công tác", "en": "A Linh goes on a business trip", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "这次出差要乘坐火车，我的行李箱太重了。", "p": ["zhè", "cì", "chū", "chāi", "yào", "chéng", "zuò", "huǒ", "chē", "", "wǒ", "de", "xíng", "li", "xiāng", "tài", "zhòng", "le", ""], "vi": "Lần này đi công tác phải đi tàu hỏa, vali của mình nặng quá.", "en": "This business trip is by train, and my suitcase is too heavy."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你都带了什么？", "p": ["nǐ", "dōu", "dài", "le", "shén", "me", ""], "vi": "Cậu mang những gì thế?", "en": "What have you packed?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "毛巾、牙膏、衣服什么的，还有很多材料。", "p": ["máo", "jīn", "", "yá", "gāo", "", "yī", "fú", "shén", "me", "de", "", "hái", "yǒu", "hěn", "duō", "cái", "liào", ""], "vi": "Khăn mặt, kem đánh răng, quần áo các thứ, còn có rất nhiều tài liệu.", "en": "Towels, toothpaste, clothes and so on, plus lots of documents."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "既然酒店有毛巾和牙膏，你就别带了，还能减少塑料袋。", "p": ["jì", "rán", "jiǔ", "diàn", "yǒu", "máo", "jīn", "hé", "yá", "gāo", "", "nǐ", "jiù", "bié", "dài", "le", "", "hái", "néng", "jiǎn", "shǎo", "sù", "liào", "dài", ""], "vi": "Khách sạn đã có khăn và kem đánh răng thì cậu đừng mang nữa, còn giảm được túi ni-lông.", "en": "Since the hotel has towels and toothpaste, don't bring them — that also cuts down on plastic bags."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "有道理，于是我又把它们拿出来了。现在轻多了！", "p": ["yǒu", "dào", "lǐ", "", "yú", "shì", "wǒ", "yòu", "bǎ", "tā", "men", "ná", "chū", "lái", "le", "", "xiàn", "zài", "qīng", "duō", "le", ""], "vi": "Có lý, thế là mình lại lấy chúng ra. Giờ nhẹ hơn nhiều rồi!", "en": "Good point — so I've taken them out again. It's much lighter now!"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "路上注意安全，到了给我发个消息。", "p": ["lù", "shàng", "zhù", "yì", "ān", "quán", "", "dào", "le", "gěi", "wǒ", "fā", "gè", "xiāo", "xī", ""], "vi": "Đi đường cẩn thận, đến nơi nhắn tin cho mình nhé.", "en": "Be safe on the way and send me a message when you arrive."}]}, {"n": 2, "zh": "短文：保护我们的地球", "vi": "Đoạn văn: Bảo vệ Trái Đất của chúng ta", "en": "Passage: Protecting our Earth", "kw": [], "lines": [{"s": "", "sp": [], "t": "地球是我们共同的家，可是现在污染越来越严重，温度也越来越高。其实保护地球并不难，每个人都可以从小事做起：少用塑料袋，不乱扔垃圾，离开房间时关灯，出门时多乘坐公共汽车。阿玲的公司还鼓励员工以骑自行车的方式上班。只要大家一起努力，地球一定会更美丽。", "p": ["dì", "qiú", "shì", "wǒ", "men", "gòng", "tóng", "de", "jiā", "", "kě", "shì", "xiàn", "zài", "wū", "rǎn", "yuè", "lái", "yuè", "yán", "zhòng", "", "wēn", "dù", "yě", "yuè", "lái", "yuè", "gāo", "", "qí", "shí", "bǎo", "hù", "dì", "qiú", "bìng", "bù", "nán", "", "měi", "gè", "rén", "dōu", "kě", "yǐ", "cóng", "xiǎo", "shì", "zuò", "qǐ", "", "shǎo", "yòng", "sù", "liào", "dài", "", "bú", "luàn", "rēng", "lā", "jī", "", "lí", "kāi", "fáng", "jiān", "shí", "guān", "dēng", "", "chū", "mén", "shí", "duō", "chéng", "zuò", "gōng", "gòng", "qì", "chē", "", "ā", "líng", "de", "gōng", "sī", "hái", "gǔ", "lì", "yuán", "gōng", "yǐ", "qí", "zì", "xíng", "chē", "de", "fāng", "shì", "shàng", "bān", "", "zhǐ", "yào", "dà", "jiā", "yì", "qǐ", "nǔ", "lì", "", "dì", "qiú", "yí", "dìng", "huì", "gèng", "měi", "lì", ""], "vi": "Trái Đất là ngôi nhà chung của chúng ta, nhưng bây giờ ô nhiễm ngày càng nghiêm trọng, nhiệt độ cũng ngày càng cao. Thật ra bảo vệ Trái Đất không khó, mỗi người đều có thể bắt đầu từ việc nhỏ: dùng ít túi ni-lông, không vứt rác bừa bãi, tắt đèn khi rời phòng, ra ngoài đi xe buýt nhiều hơn. Công ty của A Linh còn khuyến khích nhân viên đi làm bằng xe đạp. Chỉ cần mọi người cùng cố gắng, Trái Đất nhất định sẽ đẹp hơn.", "en": "The Earth is our shared home, but pollution is getting worse and temperatures keep rising. Protecting the Earth isn't actually hard; everyone can start with small things: use fewer plastic bags, don't litter, switch off the lights when you leave a room, and take the bus more often. A Linh's company even encourages staff to cycle to work. As long as we all make an effort, the Earth will surely become more beautiful."}]}]}, {"l": 15, "texts": [{"n": 1, "zh": "阿玲学弹钢琴", "vi": "A Linh học đàn piano", "en": "A Linh learns the piano", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我刚才听到有人在弹钢琴，原来是你呀！", "p": ["wǒ", "gāng", "cái", "tīng", "dào", "yǒu", "rén", "zài", "tán", "gāng", "qín", "", "yuán", "lái", "shì", "nǐ", "ya", ""], "vi": "Vừa nãy mình nghe thấy có người đánh đàn piano, hóa ra là cậu à!", "en": "I just heard someone playing the piano — so it was you!"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我才学了两个星期，弹得很笨，你千万别笑我。", "p": ["wǒ", "cái", "xué", "le", "liǎng", "gè", "xīng", "qī", "", "tán", "de", "hěn", "bèn", "", "nǐ", "qiān", "wàn", "bié", "xiào", "wǒ", ""], "vi": "Mình mới học được hai tuần, đánh vụng lắm, cậu đừng cười mình nhé.", "en": "I've only been learning for two weeks and I'm clumsy. Please don't laugh at me."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "怎么会呢？已经很棒了。你怎么想起来学钢琴了？", "p": ["zěn", "me", "huì", "ne", "", "yǐ", "jīng", "hěn", "bàng", "le", "", "nǐ", "zěn", "me", "xiǎng", "qǐ", "lái", "xué", "gāng", "qín", "le", ""], "vi": "Sao thế được? Đã hay lắm rồi. Sao cậu lại nghĩ đến việc học piano?", "en": "Of course not! It's already great. What made you think of learning the piano?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "小时候我就想学，可是家里没条件。现在终于有机会了。", "p": ["xiǎo", "shí", "hòu", "wǒ", "jiù", "xiǎng", "xué", "", "kě", "shì", "jiā", "lǐ", "méi", "tiáo", "jiàn", "", "xiàn", "zài", "zhōng", "yú", "yǒu", "jī", "huì", "le", ""], "vi": "Hồi nhỏ mình đã muốn học, nhưng nhà không có điều kiện. Bây giờ cuối cùng cũng có cơ hội.", "en": "I wanted to learn when I was little, but my family couldn't afford it. Now I finally have the chance."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你每天练多长时间？", "p": ["nǐ", "měi", "tiān", "liàn", "duō", "cháng", "shí", "jiān", ""], "vi": "Mỗi ngày cậu tập bao lâu?", "en": "How long do you practise each day?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "一个小时左右。老师表扬我进步很快，我有点儿骄傲了！", "p": ["yī", "gè", "xiǎo", "shí", "zuǒ", "yòu", "", "lǎo", "shī", "biǎo", "yáng", "wǒ", "jìn", "bù", "hěn", "kuài", "", "wǒ", "yǒu", "diǎn", "r", "jiāo", "ào", "le", ""], "vi": "Khoảng một tiếng. Thầy khen mình tiến bộ nhanh, mình hơi tự hào rồi đấy!", "en": "About an hour. My teacher praised me for improving quickly — I'm a little proud!"}]}, {"n": 2, "zh": "短文：教育孩子的方法", "vi": "Đoạn văn: Cách dạy con", "en": "Passage: How to bring up children", "kw": [], "lines": [{"s": "", "sp": [], "t": "儿童都喜欢被表扬。如果孩子做得好，父母应该及时表扬他；如果孩子粗心弄错了，也不要马上批评，而是耐心地告诉他应该怎么做。有的孩子很害羞，父母可以多鼓励他和别人交流。总之，管理孩子不能只靠批评，合适的方法比严格更重要。", "p": ["ér", "tóng", "dōu", "xǐ", "huān", "bèi", "biǎo", "yáng", "", "rú", "guǒ", "hái", "zi", "zuò", "de", "hǎo", "", "fù", "mǔ", "yīng", "gāi", "jí", "shí", "biǎo", "yáng", "tā", "", "rú", "guǒ", "hái", "zi", "cū", "xīn", "nòng", "cuò", "le", "", "yě", "bú", "yào", "mǎ", "shàng", "pī", "píng", "", "ér", "shì", "nài", "xīn", "dì", "gào", "sù", "tā", "yīng", "gāi", "zěn", "me", "zuò", "", "yǒu", "de", "hái", "zi", "hěn", "hài", "xiū", "", "fù", "mǔ", "kě", "yǐ", "duō", "gǔ", "lì", "tā", "hé", "bié", "rén", "jiāo", "liú", "", "zǒng", "zhī", "", "guǎn", "lǐ", "hái", "zi", "bù", "néng", "zhǐ", "kào", "pī", "píng", "", "hé", "shì", "de", "fāng", "fǎ", "bǐ", "yán", "gé", "gèng", "zhòng", "yào", ""], "vi": "Trẻ em đều thích được khen. Nếu con làm tốt, cha mẹ nên khen kịp thời; nếu con sơ ý làm sai, cũng đừng phê bình ngay mà nên kiên nhẫn nói cho con biết phải làm thế nào. Có những đứa trẻ rất hay xấu hổ, cha mẹ có thể khuyến khích con giao tiếp với người khác nhiều hơn. Tóm lại, dạy con không thể chỉ dựa vào phê bình, phương pháp phù hợp quan trọng hơn nghiêm khắc.", "en": "Children all love to be praised. If a child does well, parents should praise them promptly; if the child makes a careless mistake, don't criticise straight away but patiently show them what to do. Some children are shy, and parents can encourage them to talk with others more. In short, raising children can't rely on criticism alone — the right method matters more than strictness."}]}]}, {"l": 16, "texts": [{"n": 1, "zh": "阿玲办签证", "vi": "A Linh làm visa", "en": "A Linh applies for a visa", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "小雪，我要报名参加一个夏令营，可是签证到底怎么办？", "p": ["xiǎo", "xuě", "", "wǒ", "yào", "bào", "míng", "cān", "jiā", "yí", "gè", "xià", "lìng", "yíng", "", "kě", "shì", "qiān", "zhèng", "dào", "dǐ", "zěn", "me", "bàn", ""], "vi": "Tiểu Tuyết, mình muốn đăng ký trại hè, nhưng rốt cuộc làm visa thế nào?", "en": "Xiaoxue, I want to sign up for a summer camp, but how on earth do I get a visa?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你先在网上填好表格，然后去大使馆交材料。", "p": ["nǐ", "xiān", "zài", "wǎng", "shàng", "tián", "hǎo", "biǎo", "gé", "", "rán", "hòu", "qù", "dà", "shǐ", "guǎn", "jiāo", "cái", "liào", ""], "vi": "Cậu điền tờ khai trên mạng trước, sau đó đến đại sứ quán nộp hồ sơ.", "en": "First fill in the form online, then take your documents to the embassy."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "表格上的内容太多了，我恐怕会填错。", "p": ["biǎo", "gé", "shàng", "de", "nèi", "róng", "tài", "duō", "le", "", "wǒ", "kǒng", "pà", "huì", "tián", "cuò", ""], "vi": "Nội dung trong tờ khai nhiều quá, mình sợ sẽ điền sai.", "en": "There's so much on the form — I'm afraid I'll get it wrong."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别着急，冷静一点儿。我陪你一起填，千万不能马虎。", "p": ["bié", "zháo", "jí", "", "lěng", "jìng", "yì", "diǎn", "r", "", "wǒ", "péi", "nǐ", "yì", "qǐ", "tián", "", "qiān", "wàn", "bù", "néng", "mǎ", "hǔ", ""], "vi": "Đừng vội, bình tĩnh chút. Mình cùng cậu điền, tuyệt đối không được cẩu thả.", "en": "Don't worry, stay calm. I'll fill it in with you — we mustn't be careless."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "太好了！有你在，我就敢自己去大使馆了。", "p": ["tài", "hǎo", "le", "", "yǒu", "nǐ", "zài", "", "wǒ", "jiù", "gǎn", "zì", "jǐ", "qù", "dà", "shǐ", "guǎn", "le", ""], "vi": "Tốt quá! Có cậu, mình dám tự đi đại sứ quán rồi.", "en": "Wonderful! With you here, I'll dare to go to the embassy on my own."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "可别忘了带护照和照片啊！", "p": ["kě", "bié", "wàng", "le", "dài", "hù", "zhào", "hé", "zhào", "piān", "a", ""], "vi": "Nhớ đừng quên mang hộ chiếu và ảnh đấy nhé!", "en": "Just don't forget your passport and photos!"}]}, {"n": 2, "zh": "短文：尊重别人", "vi": "Đoạn văn: Tôn trọng người khác", "en": "Passage: Respecting others", "kw": [], "lines": [{"s": "", "sp": [], "t": "尊重别人是一种礼貌。拿说话来说，别人讲话时不要随便打断，要认真地听。有时候朋友输了比赛，心情不好，我们应该同情他、鼓励他，而不是笑他。当我们尊重别人时，别人也会重视我们。一个有自信的人，往往也懂得尊重别人。", "p": ["zūn", "zhòng", "bié", "rén", "shì", "yì", "zhǒng", "lǐ", "mào", "", "ná", "shuō", "huà", "lái", "shuō", "", "bié", "rén", "jiǎng", "huà", "shí", "bú", "yào", "suí", "biàn", "dǎ", "duàn", "", "yào", "rèn", "zhēn", "dì", "tīng", "", "yǒu", "shí", "hòu", "péng", "you", "shū", "le", "bǐ", "sài", "", "xīn", "qíng", "bù", "hǎo", "", "wǒ", "men", "yīng", "gāi", "tóng", "qíng", "tā", "", "gǔ", "lì", "tā", "", "ér", "bú", "shì", "xiào", "tā", "", "dāng", "wǒ", "men", "zūn", "zhòng", "bié", "rén", "shí", "", "bié", "rén", "yě", "huì", "zhòng", "shì", "wǒ", "men", "", "yí", "gè", "yǒu", "zì", "xìn", "de", "rén", "", "wǎng", "wǎng", "yě", "dǒng", "de", "zūn", "zhòng", "bié", "rén", ""], "vi": "Tôn trọng người khác là một phép lịch sự. Lấy việc nói chuyện làm ví dụ, khi người khác đang nói đừng tùy tiện ngắt lời, phải chăm chú lắng nghe. Có khi bạn bè thua cuộc thi, tâm trạng không tốt, chúng ta nên thông cảm và động viên họ chứ không phải cười họ. Khi chúng ta tôn trọng người khác, người khác cũng sẽ coi trọng chúng ta. Một người tự tin thường cũng biết tôn trọng người khác.", "en": "Respecting others is a form of politeness. Take speaking, for example: don't casually interrupt when someone is talking — listen carefully. When a friend loses a competition and feels low, we should sympathise and encourage them, not laugh at them. When we respect others, they will value us too. A confident person usually knows how to respect others as well."}]}]}, {"l": 17, "texts": [{"n": 1, "zh": "阿玲放暑假", "vi": "A Linh nghỉ hè", "en": "A Linh's summer holiday", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "快放暑假了，你有什么计划？", "p": ["kuài", "fàng", "shǔ", "jià", "le", "", "nǐ", "yǒu", "shén", "me", "jì", "huà", ""], "vi": "Sắp nghỉ hè rồi, cậu có kế hoạch gì?", "en": "The summer holiday's coming. Any plans?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我想去海边玩儿一趟，那儿比城市凉快多了。", "p": ["wǒ", "xiǎng", "qù", "hǎi", "biān", "wán", "r", "yí", "tàng", "", "nà", "r", "bǐ", "chéng", "shì", "liáng", "kuài", "duō", "le", ""], "vi": "Mình muốn đi biển chơi một chuyến, ở đó mát hơn thành phố nhiều.", "en": "I'd like to take a trip to the seaside — it's much cooler than the city."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "可是暑假的时候人特别多，到处都要排队。", "p": ["kě", "shì", "shǔ", "jià", "de", "shí", "hòu", "rén", "tè", "bié", "duō", "", "dào", "chù", "dōu", "yào", "pái", "duì", ""], "vi": "Nhưng nghỉ hè đông người lắm, chỗ nào cũng phải xếp hàng.", "en": "But it's really crowded in the summer holidays; you have to queue everywhere."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "人多倒是没关系，我就喜欢热闹。", "p": ["rén", "duō", "dào", "shì", "méi", "guān", "xì", "", "wǒ", "jiù", "xǐ", "huān", "rè", "nào", ""], "vi": "Đông người thì cũng chẳng sao, mình thích náo nhiệt mà.", "en": "Crowds don't bother me — I like a lively atmosphere."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那我们一起去吧！为了省钱，我们可以早点儿订票。", "p": ["nà", "wǒ", "men", "yì", "qǐ", "qù", "ba", "", "wèi", "le", "shěng", "qián", "", "wǒ", "men", "kě", "yǐ", "zǎo", "diǎn", "r", "dìng", "piào", ""], "vi": "Vậy mình đi cùng nhau đi! Để tiết kiệm tiền, mình có thể đặt vé sớm.", "en": "Then let's go together! To save money, we can book tickets early."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "好！虽然还有一个月，我仍然已经开始兴奋了。", "p": ["hǎo", "", "suī", "rán", "hái", "yǒu", "yí", "gè", "yuè", "", "wǒ", "réng", "rán", "yǐ", "jīng", "kāi", "shǐ", "xīng", "fèn", "le", ""], "vi": "Được! Tuy còn một tháng nữa, mình vẫn đã bắt đầu háo hức rồi.", "en": "Great! Even though it's still a month away, I'm already getting excited."}]}, {"n": 2, "zh": "短文：大海的梦", "vi": "Đoạn văn: Giấc mơ về biển", "en": "Passage: Dreaming of the sea", "kw": [], "lines": [{"s": "", "sp": [], "t": "阿玲从小就有一个梦：去看大海。第一次看到海洋时，她激动得抱住了妈妈。蓝色的海水，白色的云，活泼的孩子在沙滩上跑来跑去。她觉得大自然真是太美了。现在社会竞争越来越大，人们的生活压力也很大。有空儿的时候，去海边走走，心情就会好很多。", "p": ["ā", "líng", "cóng", "xiǎo", "jiù", "yǒu", "yí", "gè", "mèng", "", "qù", "kàn", "dà", "hǎi", "", "dì", "yī", "cì", "kàn", "dào", "hǎi", "yáng", "shí", "", "tā", "jī", "dòng", "de", "bào", "zhù", "le", "mā", "mā", "", "lán", "sè", "de", "hǎi", "shuǐ", "", "bái", "sè", "de", "yún", "", "huó", "pō", "de", "hái", "zi", "zài", "shā", "tān", "shàng", "pǎo", "lái", "pǎo", "qù", "", "tā", "jué", "de", "dà", "zì", "rán", "zhēn", "shì", "tài", "měi", "le", "", "xiàn", "zài", "shè", "huì", "jìng", "zhēng", "yuè", "lái", "yuè", "dà", "", "rén", "men", "de", "shēng", "huó", "yā", "lì", "yě", "hěn", "dà", "", "yǒu", "kòng", "r", "de", "shí", "hòu", "", "qù", "hǎi", "biān", "zǒu", "zǒu", "", "xīn", "qíng", "jiù", "huì", "hǎo", "hěn", "duō", ""], "vi": "Từ nhỏ A Linh đã có một giấc mơ: đi ngắm biển. Lần đầu tiên nhìn thấy đại dương, cô xúc động đến mức ôm chầm lấy mẹ. Nước biển xanh, mây trắng, những đứa trẻ hiếu động chạy tới chạy lui trên bãi cát. Cô thấy thiên nhiên thật là đẹp quá. Bây giờ xã hội cạnh tranh ngày càng gay gắt, áp lực cuộc sống của con người cũng rất lớn. Lúc rảnh rỗi, đi dạo bên bờ biển, tâm trạng sẽ tốt lên rất nhiều.", "en": "Ever since she was little, A Linh had a dream: to see the sea. When she first saw the ocean, she was so excited she hugged her mother. Blue water, white clouds, lively children running back and forth on the sand — she thought nature was just so beautiful. Society today is ever more competitive, and people are under a lot of pressure. When you have free time, a walk by the sea will make you feel much better."}]}]}, {"l": 18, "texts": [{"n": 1, "zh": "阿玲迷路了", "vi": "A Linh bị lạc đường", "en": "A Linh gets lost", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "喂，小雪，我好像迷路了，手机也快没电了。", "p": ["wèi", "", "xiǎo", "xuě", "", "wǒ", "hǎo", "xiàng", "mí", "lù", "le", "", "shǒu", "jī", "yě", "kuài", "méi", "diàn", "le", ""], "vi": "Alo, Tiểu Tuyết, hình như mình bị lạc đường rồi, điện thoại cũng sắp hết pin.", "en": "Hello, Xiaoxue? I think I'm lost, and my phone's nearly out of battery."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别着急，你周围有什么？", "p": ["bié", "zháo", "jí", "", "nǐ", "zhōu", "wéi", "yǒu", "shén", "me", ""], "vi": "Đừng lo, xung quanh cậu có gì?", "en": "Don't panic. What's around you?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "前面有一座桥，旁边是一个邮局。", "p": ["qián", "miàn", "yǒu", "yí", "zuò", "qiáo", "", "páng", "biān", "shì", "yí", "gè", "yóu", "jú", ""], "vi": "Phía trước có một cây cầu, bên cạnh là một bưu điện.", "en": "There's a bridge ahead, and a post office next to it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "我知道了。你过了桥一直往前走，接着往左拐，就能看到我们学校的门了。", "p": ["wǒ", "zhī", "dào", "le", "", "nǐ", "guò", "le", "qiáo", "yì", "zhí", "wǎng", "qián", "zǒu", "", "jiē", "zhe", "wǎng", "zuǒ", "guǎi", "", "jiù", "néng", "kàn", "dào", "wǒ", "men", "xué", "xiào", "de", "mén", "le", ""], "vi": "Mình biết rồi. Cậu qua cầu đi thẳng, tiếp đó rẽ trái là thấy cổng trường mình.", "en": "I know where you are. Cross the bridge, keep going straight, then turn left and you'll see our school gate."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "太好了！我真受不了自己，总是记不住路。", "p": ["tài", "hǎo", "le", "", "wǒ", "zhēn", "shòu", "bù", "liǎo", "zì", "jǐ", "", "zǒng", "shì", "jì", "bú", "zhù", "lù", ""], "vi": "Tốt quá! Mình chịu hết nổi bản thân, lúc nào cũng không nhớ đường.", "en": "Great! I can't stand myself — I can never remember the way."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "下次出门前先在地图上查一下地址，就安全多了。", "p": ["xià", "cì", "chū", "mén", "qián", "xiān", "zài", "dì", "tú", "shàng", "chá", "yí", "xià", "dì", "zhǐ", "", "jiù", "ān", "quán", "duō", "le", ""], "vi": "Lần sau trước khi ra ngoài tra địa chỉ trên bản đồ trước, sẽ an toàn hơn nhiều.", "en": "Next time check the address on the map before you go out — it's much safer."}]}, {"n": 2, "zh": "短文：网上付款", "vi": "Đoạn văn: Thanh toán trực tuyến", "en": "Passage: Paying online", "kw": [], "lines": [{"s": "", "sp": [], "t": "现在，用手机付款越来越普遍了。买东西、坐车、吃饭，只要输入密码，几秒钟就能完成。这种技术给生活带来了很多方便。除此以外，在网站上还能买火车票、交电费。不过，我们也要注意安全，不要把密码告诉别人，也不要随便打开不认识的网站。是否安全，关键在于我们自己是否小心。", "p": ["xiàn", "zài", "", "yòng", "shǒu", "jī", "fù", "kuǎn", "yuè", "lái", "yuè", "pǔ", "biàn", "le", "", "mǎi", "dōng", "xi", "", "zuò", "chē", "", "chī", "fàn", "", "zhǐ", "yào", "shū", "rù", "mì", "mǎ", "", "jǐ", "miǎo", "zhōng", "jiù", "néng", "wán", "chéng", "", "zhè", "zhǒng", "jì", "shù", "gěi", "shēng", "huó", "dài", "lái", "le", "hěn", "duō", "fāng", "biàn", "", "chú", "cǐ", "yǐ", "wài", "", "zài", "wǎng", "zhàn", "shàng", "hái", "néng", "mǎi", "huǒ", "chē", "piào", "", "jiāo", "diàn", "fèi", "", "bú", "guò", "", "wǒ", "men", "yě", "yào", "zhù", "yì", "ān", "quán", "", "bú", "yào", "bǎ", "mì", "mǎ", "gào", "sù", "bié", "rén", "", "yě", "bú", "yào", "suí", "biàn", "dǎ", "kāi", "bú", "rèn", "shí", "de", "wǎng", "zhàn", "", "shì", "fǒu", "ān", "quán", "", "guān", "jiàn", "zài", "yú", "wǒ", "men", "zì", "jǐ", "shì", "fǒu", "xiǎo", "xīn", ""], "vi": "Bây giờ thanh toán bằng điện thoại ngày càng phổ biến. Mua đồ, đi xe, ăn uống, chỉ cần nhập mật khẩu, vài giây là xong. Công nghệ này mang lại rất nhiều tiện lợi cho cuộc sống. Ngoài ra, trên trang web còn có thể mua vé tàu, trả tiền điện. Tuy nhiên, chúng ta cũng phải chú ý an toàn, đừng nói mật khẩu cho người khác, cũng đừng tùy tiện mở những trang web lạ. An toàn hay không, then chốt là ở chỗ bản thân chúng ta có cẩn thận hay không.", "en": "Paying by phone is becoming more and more common. Shopping, taking a ride, eating out — just enter your password and it's done in a few seconds. This technology brings a lot of convenience. Besides that, you can buy train tickets and pay electricity bills on websites. But we must stay safe: don't tell anyone your password, and don't casually open unfamiliar websites. Whether it's safe or not depends on whether we ourselves are careful."}]}]}, {"l": 19, "texts": [{"n": 1, "zh": "阿玲找房子", "vi": "A Linh tìm nhà", "en": "A Linh looks for a flat", "kw": [], "lines": [{"s": "阿玲", "sp": ["ā", "líng"], "t": "我想租一个离学校近的房子，你有什么好主意吗？", "p": ["wǒ", "xiǎng", "zū", "yí", "gè", "lí", "xué", "xiào", "jìn", "de", "fáng", "zi", "", "nǐ", "yǒu", "shén", "me", "hǎo", "zhǔ", "yi", "ma", ""], "vi": "Mình muốn thuê một căn nhà gần trường, cậu có ý gì hay không?", "en": "I want to rent a place near school. Any good ideas?"}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你可以在网上找找，或者直接给房东打电话。", "p": ["nǐ", "kě", "yǐ", "zài", "wǎng", "shàng", "zhǎo", "zhǎo", "", "huò", "zhě", "zhí", "jiē", "gěi", "fáng", "dōng", "dǎ", "diàn", "huà", ""], "vi": "Cậu có thể tìm trên mạng, hoặc gọi thẳng cho chủ nhà.", "en": "You could look online, or phone the landlords directly."}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "我刚才打了好几次，都占线。", "p": ["wǒ", "gāng", "cái", "dǎ", "le", "hǎo", "jǐ", "cì", "", "dōu", "zhàn", "xiàn", ""], "vi": "Mình vừa gọi mấy lần rồi, đều máy bận.", "en": "I've just called several times, but the line's always busy."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "别急，谁都有忙的时候。这个房子的厨房大不大？", "p": ["bié", "jí", "", "shéi", "dōu", "yǒu", "máng", "de", "shí", "hòu", "", "zhè", "ge", "fáng", "zi", "de", "chú", "fáng", "dà", "bú", "dà", ""], "vi": "Đừng vội, ai cũng có lúc bận. Căn này bếp có rộng không?", "en": "Don't worry, everyone's busy sometimes. Is the kitchen in this one big?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "挺大的，我可以在里面包饺子！总的来说，我很满意。", "p": ["tǐng", "dà", "de", "", "wǒ", "kě", "yǐ", "zài", "lǐ", "miàn", "bāo", "jiǎo", "zi", "", "zǒng", "de", "lái", "shuō", "", "wǒ", "hěn", "mǎn", "yì", ""], "vi": "Khá rộng, mình có thể gói sủi cảo trong đó! Nói chung là mình rất hài lòng.", "en": "Pretty big — I could make dumplings in there! Overall, I'm very happy with it."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "那就快去看看吧，好房子可不等人。", "p": ["nà", "jiù", "kuài", "qù", "kàn", "kàn", "ba", "", "hǎo", "fáng", "zi", "kě", "bù", "děng", "rén", ""], "vi": "Vậy mau đi xem đi, nhà đẹp không chờ người đâu.", "en": "Then go and see it quickly — good flats don't wait for anyone."}]}, {"n": 2, "zh": "短文：学一门功夫", "vi": "Đoạn văn: Học một môn võ", "en": "Passage: Learning a martial art", "kw": [], "lines": [{"s": "", "sp": [], "t": "阿玲这个学期报名学中国功夫。第一节课，老师先教大家打招呼，然后让大家抬胳膊、转身。阿玲觉得很难，可是老师说：“学功夫的关键在于坚持，谁都是从不会到会的。”现在，阿玲每天早上都练习半个小时。她说，功夫不仅让她身体更好，还让她更有耐心了。", "p": ["ā", "líng", "zhè", "ge", "xué", "qī", "bào", "míng", "xué", "zhōng", "guó", "gōng", "fu", "", "dì", "yī", "jié", "kè", "", "lǎo", "shī", "xiān", "jiāo", "dà", "jiā", "dǎ", "zhāo", "hu", "", "rán", "hòu", "ràng", "dà", "jiā", "tái", "gē", "bó", "", "zhuǎn", "shēn", "", "ā", "líng", "jué", "de", "hěn", "nán", "", "kě", "shì", "lǎo", "shī", "shuō", "", "", "xué", "gōng", "fu", "de", "guān", "jiàn", "zài", "yú", "jiān", "chí", "", "shéi", "dōu", "shì", "cóng", "bú", "huì", "dào", "huì", "de", "", "", "xiàn", "zài", "", "ā", "líng", "měi", "tiān", "zǎo", "shàng", "dōu", "liàn", "xí", "bàn", "gè", "xiǎo", "shí", "", "tā", "shuō", "", "gōng", "fu", "bù", "jǐn", "ràng", "tā", "shēn", "tǐ", "gèng", "hǎo", "", "hái", "ràng", "tā", "gèng", "yǒu", "nài", "xīn", "le", ""], "vi": "Học kỳ này A Linh đăng ký học võ Trung Quốc. Buổi học đầu tiên, thầy dạy mọi người chào hỏi trước, sau đó cho mọi người nâng tay, xoay người. A Linh thấy rất khó, nhưng thầy nói: \"Mấu chốt của việc học võ là ở sự kiên trì, ai cũng từ không biết đến biết.\" Bây giờ sáng nào A Linh cũng luyện tập nửa tiếng. Cô nói, võ thuật không chỉ giúp cô khỏe hơn mà còn giúp cô kiên nhẫn hơn.", "en": "This term A Linh signed up for Chinese kung fu. In the first class the teacher taught everyone how to greet, then had them raise their arms and turn around. A Linh found it hard, but the teacher said, \"The key to learning kung fu is persistence — everyone goes from not knowing to knowing.\" Now A Linh practises for half an hour every morning. She says kung fu has not only made her healthier but also more patient."}]}]}, {"l": 20, "texts": [{"n": 1, "zh": "阿玲和小雪去旅行", "vi": "A Linh và Tiểu Tuyết đi du lịch", "en": "A Linh and Xiaoxue go travelling", "kw": [], "lines": [{"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "航班推迟了一个小时，我们究竟几点出发？", "p": ["háng", "bān", "tuī", "chí", "le", "yí", "gè", "xiǎo", "shí", "", "wǒ", "men", "jiū", "jìng", "jǐ", "diǎn", "chū", "fā", ""], "vi": "Chuyến bay hoãn một tiếng rồi, rốt cuộc mấy giờ mình xuất phát?", "en": "The flight's been delayed an hour. So what time are we actually leaving?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "别着急，我们先去换登机牌，然后吃点儿东西。", "p": ["bié", "zháo", "jí", "", "wǒ", "men", "xiān", "qù", "huàn", "dēng", "jī", "pái", "", "rán", "hòu", "chī", "diǎn", "r", "dōng", "xi", ""], "vi": "Đừng vội, mình đi đổi thẻ lên máy bay trước, rồi ăn chút gì đó.", "en": "Don't worry, let's get our boarding passes first and then grab something to eat."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "好。这次去成都，你最想吃什么？", "p": ["hǎo", "", "zhè", "cì", "qù", "chéng", "dū", "", "nǐ", "zuì", "xiǎng", "chī", "shén", "me", ""], "vi": "Được. Lần này đi Thành Đô, cậu muốn ăn gì nhất?", "en": "OK. On this trip to Chengdu, what do you most want to eat?"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "当然是小吃！听说那儿的菜又香又辣。", "p": ["dāng", "rán", "shì", "xiǎo", "chī", "", "tīng", "shuō", "nà", "r", "de", "cài", "yòu", "xiāng", "yòu", "là", ""], "vi": "Tất nhiên là đồ ăn vặt! Nghe nói món ăn ở đó vừa thơm vừa cay.", "en": "Street food, of course! I hear the food there is fragrant and spicy."}, {"s": "小雪", "sp": ["xiǎo", "xuě"], "t": "你一到那儿就会爱上它的。来，为我们的旅行干杯！", "p": ["nǐ", "yí", "dào", "nà", "r", "jiù", "huì", "ài", "shàng", "tā", "de", "", "lái", "", "wèi", "wǒ", "men", "de", "lǚ", "xíng", "gān", "bēi", ""], "vi": "Cậu vừa đến đó là sẽ yêu nó ngay. Nào, cạn ly cho chuyến du lịch của chúng mình!", "en": "You'll fall in love with it the moment you arrive. Come on — cheers to our trip!"}, {"s": "阿玲", "sp": ["ā", "líng"], "t": "干杯！说着说着，我都饿了。", "p": ["gān", "bēi", "", "shuō", "zhe", "shuō", "zhe", "", "wǒ", "dōu", "è", "le", ""], "vi": "Cạn ly! Nói mãi nói mãi, mình đói luôn rồi.", "en": "Cheers! All this talking is making me hungry."}]}, {"n": 2, "zh": "短文：旅行的意义", "vi": "Đoạn văn: Ý nghĩa của du lịch", "en": "Passage: Why we travel", "kw": [], "lines": [{"s": "", "sp": [], "t": "旅行可以让我们看到不同的风景，认识不同的民族，尝到各地的小吃。阿玲第一次来中国时，普通话说得不太好，常常闹笑话。现在她不但能和当地人对话，还能帮朋友收拾行李、安排路线。她说，旅行最大的收获不是照片，而是在路上成长起来的自己。", "p": ["lǚ", "xíng", "kě", "yǐ", "ràng", "wǒ", "men", "kàn", "dào", "bù", "tóng", "de", "fēng", "jǐng", "", "rèn", "shí", "bù", "tóng", "de", "mín", "zú", "", "cháng", "dào", "gè", "dì", "de", "xiǎo", "chī", "", "ā", "líng", "dì", "yī", "cì", "lái", "zhōng", "guó", "shí", "", "pǔ", "tōng", "huà", "shuō", "de", "bú", "tài", "hǎo", "", "cháng", "cháng", "nào", "xiào", "huà", "", "xiàn", "zài", "tā", "bú", "dàn", "néng", "hé", "dāng", "dì", "rén", "duì", "huà", "", "hái", "néng", "bāng", "péng", "you", "shōu", "shí", "xíng", "li", "", "ān", "pái", "lù", "xiàn", "", "tā", "shuō", "", "lǚ", "xíng", "zuì", "dà", "de", "shōu", "huò", "bú", "shì", "zhào", "piān", "", "ér", "shì", "zài", "lù", "shàng", "chéng", "zhǎng", "qǐ", "lái", "de", "zì", "jǐ", ""], "vi": "Du lịch giúp chúng ta ngắm những cảnh sắc khác nhau, làm quen với những dân tộc khác nhau, nếm thử món ăn vặt ở khắp nơi. Lần đầu tiên A Linh đến Trung Quốc, tiếng phổ thông nói chưa tốt lắm, thường xuyên nói nhầm gây cười. Bây giờ cô không những có thể trò chuyện với người địa phương mà còn giúp bạn bè thu dọn hành lý, sắp xếp lộ trình. Cô nói, thu hoạch lớn nhất của du lịch không phải là những tấm ảnh, mà là bản thân đã trưởng thành trên đường đi.", "en": "Travel lets us see different scenery, meet different peoples and taste snacks from all over. When A Linh first came to China, her Mandarin wasn't very good and she often made funny mistakes. Now she can not only chat with locals but also help friends pack and plan their routes. She says the greatest reward of travel isn't the photos but the person you grow into along the way."}]}]}];
